'use strict';
/* ============================================================
   APEX — an ode to the international game (cricket). Application.
   Same grammar as the other odes: River · Grounds · Stage.
   Reads the core archive (results, player-season figures, registers, titles);
   scorecards arrive per season from DETAILS (embedded offline, fetched on the site).
   ============================================================ */
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const PACK=window.PACK||(()=>{const packed=atob(document.getElementById('archive-data').textContent.trim());const bytes=new Uint8Array(packed.length);for(let i=0;i<packed.length;i++)bytes[i]=packed.charCodeAt(i);return JSON.parse(pako.ungzip(bytes,{to:'string'}));})();
const A=PACK.core, DETAILS=PACK.details||{}, DETAIL_URL=PACK.detailUrl||null;
const RM=matchMedia('(prefers-reduced-motion: reduce)').matches;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n==null?'—':Number.isInteger(n)?n.toLocaleString('en'):(Math.round(n*10)/10).toString();
const pct=(a,b)=>b?Math.round(a/b*1000)/10:0;
const day=d=>d?new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}):'—';
const dm=d=>d?new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'}):'—';
const lum=hex=>{let m=/^#?([0-9a-f]{6})$/i.exec(hex||'');if(!m)return .5;let n=parseInt(m[1],16),r=(n>>16)/255,g=(n>>8&255)/255,b=(n&255)/255;const f=c=>c<=.03928?c/12.92:((c+.055)/1.055)**2.4;return .2126*f(r)+.7152*f(g)+.0722*f(b);};
const onColor=hex=>lum(hex)>.42?'#07080a':'#f4f4f2';
const mixHex=(a,b,t)=>{const p=h=>{const m=/^#?([0-9a-f]{6})$/i.exec(h);if(!m)return [128,128,128];const n=parseInt(m[1],16);return [n>>16,n>>8&255,n&255];};const x=p(a),y=p(b);return '#'+x.map((v,i)=>Math.round(v*t+y[i]*(1-t)).toString(16).padStart(2,'0')).join('');};
const hsl2hex=(h,s,l)=>{s/=100;l/=100;const k=n=>(n+h/30)%12,a=s*Math.min(l,1-l),f=n=>l-a*Math.max(-1,Math.min(k(n)-3,Math.min(9-k(n),1)));return '#'+[f(0),f(8),f(4)].map(v=>Math.round(v*255).toString(16).padStart(2,'0')).join('');};

/* ---------- sides ---------- */
const TEAMS=A.teams, MAJOR=Object.keys(TEAMS).filter(k=>TEAMS[k].major);
const hueCache={};
const nat=n=>{const t=TEAMS[n];if(t)return {id:n,name:t.n||n,code:t.abbr||n.slice(0,3).toUpperCase(),color:t.c,secondary:t.c2||t.c,major:!!t.major,flag:t.flag};if(hueCache[n])return hueCache[n];let h=0;for(const ch of String(n))h=(h*31+ch.charCodeAt(0))>>>0;return hueCache[n]={id:n,name:n,code:n.replace(/[^A-Za-z]/g,'').slice(0,3).toUpperCase(),color:hsl2hex(h%360,35,60),secondary:'#cfd3da',major:false};};
const color=n=>nat(n).color, code=n=>nat(n).code;
const teamVar=n=>`--team:${color(n)}`;
const FORMATS=['Test','ODI','T20I'];

/* ---------- matches ---------- */
const MATCHES=A.games.map(m=>({...m,year:m.y,home:m.teams[0],away:m.teams[1],draw:m.result==='draw'||m.result==='tie',nr:m.result==='no result',loser:m.winner?(m.teams[0]===m.winner?m.teams[1]:m.teams[0]):null,recorded:!!(m.v&&A.venues[m.v]&&!A.venues[m.v].locationOnly),marginN:(()=>{const mm=/^(\d+)\s+(run|wicket)/.exec(m.margin||'');return mm?{n:+mm[1],by:mm[2]}:null;})()}));
const byId=Object.fromEntries(MATCHES.map(m=>[m.id,m]));
const VENUES=A.venues; const groundName=id=>VENUES[id]?.n||'Ground not recorded';
const PLAYERS=A.players; const pname=id=>PLAYERS[id]?.n||id;
const PS=A.ps.map(r=>Object.fromEntries(A.psFields.map((k,i)=>[k,r[i]])));
const CHAMPS=A.champions;

/* ---------- lens: gender + format (the masthead selects), then era + season as everywhere ---------- */
const state={gender:'M',fmt:'all',era:'all',year:null,tab:'season',match:null,nation:null,player:null,ground:null,lens:'wins',plens:'runs',heat:'rate',duelBy:'n',dA:null,dB:null,gridSort:'count',gridFind:'',gridMin:5,focusTeam:null,whole:false,find2:''};
const inLens=m=>m.g===state.gender&&(state.fmt==='all'||m.f===state.fmt);
let S=[],byYear={},FIRST_YEAR=0,LAST_YEAR=0;
function rebuildSeasons(){const map={};for(const m of MATCHES){if(!inLens(m))continue;(map[m.year]||(map[m.year]={year:m.year,matches:[]})).matches.push(m);}S=Object.keys(map).map(Number).sort((a,b)=>a-b).map(y=>map[y]);byYear=Object.fromEntries(S.map(s=>[s.year,s]));FIRST_YEAR=S[0]?.year||1877;LAST_YEAR=S[S.length-1]?.year||2026;seasonBest={};riverModel=null;if(!byYear[state.year])state.year=LAST_YEAR;}
const ERAS=[["origins","The first Tests",1877,1914,"Test cricket only, from the first match at Melbourne in 1877: timeless and multi-day Tests, the Ashes from 1882, South Africa's entry in 1889."],
["interwar","Between the wars",1920,1947,"Bradman’s decades and Bodyline; West Indies, New Zealand and India join Test cricket."],
["postwar","Post-war",1948,1970,"Tours by air, the tied Test of 1960, Pakistan's entry, and South Africa's last Test before isolation in 1970."],
["oneday","The one-day age",1971,1991,"The first one-day international in 1971, World Cups in 1975, 1979, 1983 and 1987, Sri Lanka's first Test in 1982."],
["colour","Coloured clothing",1992,2004,"White balls and coloured clothing, South Africa's return, Zimbabwe and Bangladesh at Test level."],
["t20","The T20 revolution",2005,2015,"The first T20 international in 2005, T20 World Cups from 2007, decision reviews, franchise leagues reshaping the calendar."],
["three","Three formats",2016,2026,"The World Test Championship, Afghanistan and Ireland at Test level from 2018, the women's game at full strength across all three formats."]].map(e=>({id:e[0],name:e[1],from:e[2],to:e[3],text:e[4]}));
const ERA_SHORT={origins:'First Tests',interwar:'Between the wars',postwar:'Post-war',oneday:'One-day age',colour:'Coloured clothing',t20:'T20 revolution',three:'Three formats'}
const ERA_TINY={origins:'Origins',interwar:'Interwar',postwar:'Post-war',oneday:'One-day',colour:'Colour',t20:'T20',three:'3 formats'};
const ERA_CHIPS={origins:['Tests only','Ashes from 1882','Timeless Tests'],interwar:['Tests only','Bodyline 1932–33','Three new Test nations'],postwar:['Tests only','Tied Test 1960','Isolation from 1970'],oneday:['ODI from 1971','World Cup from 1975','Sri Lanka Tests 1982'],colour:['White ball, coloured kit','South Africa back, 1991','Zimbabwe, Bangladesh Tests'],t20:['T20I from 2005','T20 World Cup 2007','Decision reviews'],three:['World Test Championship','Afghanistan, Ireland Tests 2018','Women’s game at full strength']};
for(const e of ERAS)e.ball={label:'The game of the era',features:ERA_CHIPS[e.id],svg:ballSvg(e)};
function ballSvg(e){return `<svg viewBox="0 0 300 150" aria-hidden="true"><g stroke="#cfd3da" stroke-width="5" stroke-linecap="round" fill="none"><path d="M64 138V60M80 138V60M96 138V60"/><path d="M62 58h20M78 58h20" stroke-width="4"/></g><g transform="translate(200 80)"><circle r="40" fill="var(--accent)" opacity=".9"/><path d="M-40 0a40 40 0 0 1 80 0" fill="none" stroke="#07080a" stroke-width="2.5" opacity=".6" transform="rotate(-30)"/><path d="M-40 0a40 40 0 0 0 80 0" fill="none" stroke="#07080a" stroke-width="2.5" opacity=".6" transform="rotate(-30)"/><path d="M-36-18 -34-14M-30-27 -27-23M-22-33 -20-29M-13-37 -12-33M-3-39 -3-35M7-39 7-35M17-37 16-33M26-33 24-29M33-27 30-23" stroke="#07080a" stroke-width="2" opacity=".5"/></g><line x1="10" y1="140" x2="290" y2="140" stroke="#2e333d" stroke-width="2"/><text x="150" y="30" text-anchor="middle" font-family="JetBrains Mono,monospace" font-size="10" letter-spacing="2" fill="#8b9099">${e.from}–${e.to}</text></svg>`;}
const eraOf=y=>ERAS.find(e=>y>=e.from&&y<=e.to)||ERAS[ERAS.length-1];
const eraRange=()=>state.era==='all'?[FIRST_YEAR,LAST_YEAR]:(e=>[e.from,e.to])(ERAS.find(e=>e.id===state.era));
const inEraYear=y=>{const [a,b]=eraRange();return y>=a&&y<=b;};
const eraSeasons=()=>S.filter(s=>inEraYear(s.year));
const eraMatches=()=>eraSeasons().flatMap(s=>s.matches);
const lensLabel=()=>`${state.gender==='M'?'Men':'Women'} · ${state.fmt==='all'?'all formats':state.fmt}`;
const eraLabel=()=>(state.era==='all'?`All eras · ${FIRST_YEAR}–${LAST_YEAR}`:(e=>`${e.name} · ${e.from}–${e.to}`)(ERAS.find(e=>e.id===state.era)))+' · '+lensLabel();

/* ---------- aggregates ---------- */
const resClass=(m,side)=>m.nr?'N':m.draw?'D':m.winner===side?'W':'L';
function natStats(ms){const map={};for(const m of ms){for(const side of m.teams){const opp=side===m.teams[0]?m.teams[1]:m.teams[0];let a=map[side]||(map[side]={id:side,p:0,w:0,l:0,d:0,nr:0,first:m.year,last:m.year,grounds:new Set(),opps:new Set(),cups:0,big:null,cur:0,best:0,hi:0,byF:{}});
  a.p++;const r=resClass(m,side);if(r==='W'){a.w++;a.cur++;if(a.cur>a.best)a.best=a.cur;if(m.marginN&&(!a.big||(m.marginN.by==='run'&&m.marginN.n>(a.big.marginN?.by==='run'?a.big.marginN.n:0))))a.big=m;}else if(r==='L'){a.l++;a.cur=0;}else if(r==='D'){a.d++;a.cur=0;}else a.nr++;
  const f=a.byF[m.f]||(a.byF[m.f]={p:0,w:0,l:0,d:0});f.p++;if(r==='W')f.w++;else if(r==='L')f.l++;else if(r==='D')f.d++;
  for(const sc of m.sc||[])if(sc[0]===side&&!sc[6]&&sc[1]>a.hi)a.hi=sc[1];
  a.first=Math.min(a.first,m.year);a.last=Math.max(a.last,m.year);if(m.recorded)a.grounds.add(m.v);a.opps.add(opp);}}
  const cupsOf=id=>CHAMPS.filter(c=>c.g===state.gender&&c.w.includes(id)&&inEraYear(c.y)&&(state.fmt==='all'||c.f===state.fmt)).length;
  return Object.values(map).map(a=>({...a,wins:a.w,rate:pct(a.w,a.p),streak:a.best,cups:cupsOf(a.id),decided:a.p-a.nr}));}
const LENSES={wins:['Wins','Matches won in the lens.'],rate:['Win rate %','Wins divided by all matches, draws and no-results included. Minimum 10 matches.'],p:['Matches','Matches played in the lens.'],cups:['ICC titles','World Cups, T20 World Cups, Champions Trophies and World Test Championships won.'],streak:['Longest winning run','Consecutive wins inside the lens.'],hi:['Highest total','Highest innings total in the lens; totals exist only where a scorecard does (2001 on).']};
const PLENSES={runs:['Runs','Runs scored, from the recorded player-season figures.'],wickets:['Wickets','Wickets taken.'],games:['Matches','Matches with recorded figures.'],hundreds:['Hundreds','Centuries.'],fifties:['Fifties','Half-centuries, excluding centuries.'],batavg:['Batting average','Runs per dismissal. Minimum 20 innings.'],bowlavg:['Bowling average','Runs conceded per wicket, lowest first. Minimum 20 wickets.'],catches:['Catches','Catches in the field.']};
const recordOrder=(a,b)=>(b.w-b.l)-(a.w-a.l)||b.rate-a.rate||b.w-a.w;
const rankRecords=(ms,minP)=>{const st=natStats(ms);const maxP=Math.max(0,...st.map(a=>a.p));const min=Math.min(Math.max(minP,Math.round(maxP*0.4)),maxP);return st.filter(a=>a.p>=min).sort(recordOrder);};
const bestRecord=(ms,minP)=>rankRecords(ms,minP)[0]||null;
let seasonBest={};function champOf(s){if(seasonBest[s.year]!==undefined)return seasonBest[s.year];const b=bestRecord(s.matches,3);const cups=CHAMPS.filter(c=>c.y===s.year&&c.g===state.gender&&(state.fmt==='all'||c.f===state.fmt));return seasonBest[s.year]={best:b,cups};}

/* ---------- theme ---------- */
function applyTheme(){let sel=$('#theme'),v=sel.value,root=document.documentElement,acc,sec,ter,ink;
  if(v==='champion'){const n=state.whole?bestRecord(eraMatches(),10)?.id:champOf(byYear[state.year]).best?.id;const t=n?nat(n):null;acc=t?t.color:'#007749';sec=t?t.secondary:'#FFB81C';ter='#0b1713';ink=onColor(acc);sel.options[0].textContent=`Best record’s colours · ${n||'—'}`;}
  else{const t=nat(v);acc=t.color;sec=t.secondary;ter='#0b1713';ink=onColor(acc);}
  root.style.setProperty('--accent',acc);root.style.setProperty('--accent2',sec);root.style.setProperty('--accent3',ter);root.style.setProperty('--on-accent',ink);}

/* ---------- the toss (the opening, once per visit) ---------- */
function lightsOut(){const box=$('#lights');let seen=false;try{seen=sessionStorage.getItem('apex-toss')==='1';}catch(e){}
  const out=()=>{if(!box.isConnected)return;box.classList.add('out');setTimeout(()=>box.remove(),800);try{sessionStorage.setItem('apex-toss','1');}catch(e){}};
  if(seen||RM){box.remove();return;}
  setTimeout(()=>box.classList.add('go'),400);setTimeout(()=>box.classList.add('over'),2400);setTimeout(out,3300);
  $('#skipLights').addEventListener('click',out);document.addEventListener('keydown',e=>{if(box.isConnected&&(e.key==='Enter'||e.key==='Escape'||e.key===' '))out();},{once:true});}

/* ---------- the River ---------- */
function smooth(pts){if(pts.length<3)return pts.map((p,i)=>(i?'L':'')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join('');let d='';for(let i=0;i<pts.length-1;i++){const p0=pts[i-1]||pts[i],p1=pts[i],p2=pts[i+1],p3=pts[i+2]||p2;const c1=[p1[0]+(p2[0]-p0[0])/6,p1[1]+(p2[1]-p0[1])/6],c2=[p2[0]-(p3[0]-p1[0])/6,p2[1]-(p3[1]-p1[1])/6];d+=`C${c1[0].toFixed(1)} ${c1[1].toFixed(1)} ${c2[0].toFixed(1)} ${c2[1].toFixed(1)} ${p2[0].toFixed(1)} ${p2[1].toFixed(1)}`;}return d;}
let riverModel=null;
function buildRiver(){const years=S.map(s=>s.year),shares=[],totals=[],champs=[];const teamFirst={},teamTotal={};
  for(const s of S){const w={};let tot=0;for(const m of s.matches){if(m.nr)continue;if(m.draw){w[m.home]=(w[m.home]||0)+.5;w[m.away]=(w[m.away]||0)+.5;}else if(m.winner)w[m.winner]=(w[m.winner]||0)+1;tot+=1;}
    for(const t in w){if(teamFirst[t]===undefined)teamFirst[t]=s.year;teamTotal[t]=(teamTotal[t]||0)+w[t];}
    const c=champOf(s);shares.push(w);totals.push(tot);champs.push({d:c.best?.id,t:c.cups[0]?.w[0]||c.best?.id,rec:c.best?`${c.best.w}–${c.best.l}–${c.best.d}`:'',cups:c.cups,races:s.matches.length});}
  const teams=Object.keys(teamFirst).sort((a,b)=>teamFirst[a]-teamFirst[b]||teamTotal[b]-teamTotal[a]);riverModel={years,shares,totals,champs,teams,teamTotal};}
function drawRiver(){
  if(!riverModel)buildRiver();const {years,shares,totals,champs,teams,teamTotal}=riverModel;
  const svg=$('#riverSvg'),box=svg.getBoundingClientRect(),W=Math.max(320,box.width),H=Math.max(200,box.height);svg.setAttribute('viewBox',`0 0 ${W} ${H}`);
  if(!years.length){svg.innerHTML='';$('#riverAxis').innerHTML='';$('#riverLegend').innerHTML='';return;}
  const era=state.era==='all'?null:ERAS.find(e=>e.id===state.era);
  let i0=era?years.findIndex(y=>y>=era.from):0,i1=era?years.length-1-[...years].reverse().findIndex(y=>y<=era.to):years.length-1;if(i0<0||i1<i0){i0=0;i1=years.length-1;}const n=i1-i0+1;
  const padL=8,padR=era?64:56,top=40,bottom=26,plotH=H-top-bottom;
  const slotW=n===1?(W-padL-padR)*.42:(W-padL-padR)/(n-1);const x=i=>n===1?padL+(W-padL-padR)/2:padL+(i-i0)*slotW;
  const maxRaces=Math.max(1,...champs.slice(i0,i1+1).map(c=>c.races));const thick=i=>plotH*(era?0.45+0.55*champs[i].races/maxRaces:0.18+0.82*Math.sqrt(champs[i].races/maxRaces));const y0=i=>top+(plotH-thick(i))/2;
  const cum=years.map(()=>0);let bands='';const eraTotal={};for(let i=i0;i<=i1;i++)for(const t in shares[i])eraTotal[t]=(eraTotal[t]||0)+shares[i][t];
  const drawTeams=era?teams.filter(t=>eraTotal[t]>0):teams;
  for(const t of drawTeams){const up=[],down=[];let any=false;for(let i=i0;i<=i1;i++){const sh=totals[i]?(shares[i][t]||0)/totals[i]:0;const a=y0(i)+cum[i]*thick(i);const b=a+sh*thick(i);cum[i]+=sh;up.push([x(i),a]);down.push([x(i),b]);if(sh>0)any=true;}if(!any)continue;
    if(n===1){const w=slotW/2;up.unshift([up[0][0]-w,up[0][1]]);up.push([up[1][0]+w,up[1][1]]);down.unshift([down[0][0]-w,down[0][1]]);down.push([down[1][0]+w,down[1][1]]);}
    const dn=down.reverse();const d='M'+up[0][0].toFixed(1)+' '+up[0][1].toFixed(1)+smooth(up)+'L'+dn[0][0].toFixed(1)+' '+dn[0][1].toFixed(1)+smooth(dn)+'Z';const tot=era?eraTotal[t]:teamTotal[t];
    bands+=`<path class="band${state.focusTeam===t?' focus':''}" data-t="${esc(t)}" d="${d}" fill="${color(t)}" stroke="#07080a" stroke-width=".5"><title>${esc(t)} · ${fmt(Math.round(tot))} wins ${era?'in this era':'since '+years[shares.findIndex(s=>s[t])]}</title></path>`;}
  let eras='';if(era){eras=`<text class="era-label" x="${padL}" y="${top-14}" style="fill:var(--accent)">${esc(era.name)} · ${era.from}–${era.to} · ${drawTeams.length} sides won a match</text>`;}
  else for(const e of ERAS){const k=years.findIndex(y=>y>=e.from);if(k<0)continue;const xx=x(k);const nxt=ERAS[ERAS.indexOf(e)+1];const nk=nxt?years.findIndex(y=>y>=nxt.from):-1;const slot=(nk>=0?x(nk):W)-xx;const fitW=l=>l.length*7.9+10<=slot;let label=ERA_SHORT[e.id]||e.name;if(!fitW(label))label=ERA_TINY[e.id]||'';const fits=!!label&&fitW(label);eras+=`<line class="era-line" x1="${xx.toFixed(1)}" y1="${top-6}" x2="${xx.toFixed(1)}" y2="${H-bottom+4}"/>${fits?`<text class="era-label" x="${(xx+5).toFixed(1)}" y="${top-14}">${esc(label)}</text>`:''}`;}
  let strip='',hits='';for(let i=i0;i<=i1;i++){const w=slotW;const c=champs[i];strip+=`<rect x="${(x(i)-w/2).toFixed(1)}" y="${H-bottom+8}" width="${Math.max(1,w-1).toFixed(1)}" height="8" fill="${c.cups.length?color(c.cups[0].w[0]):c.t?mixHex(color(c.t),'#12141a',.45):'#333'}" rx="1"><title>${years[i]} · ${c.cups.length?c.cups.map(cp=>cp.label+': '+cp.w.join(' & ')).join(' · '):'best record '+esc(c.d||'—')+' '+c.rec}</title></rect>`;hits+=`<rect class="yearhit" data-y="${years[i]}" x="${(x(i)-w/2).toFixed(1)}" y="0" width="${w.toFixed(1)}" height="${H}"/>`;}
  const si=years.indexOf(state.year);const selX=n>1&&!state.whole&&si>=i0&&si<=i1?x(si):-10;
  svg.innerHTML=`<g id="bands">${bands}</g>${eras}<g>${strip}</g><line class="cursor" id="riverCursor" x1="0" y1="${top-4}" x2="0" y2="${H-bottom+4}"/><line x1="${selX.toFixed(1)}" y1="${top-4}" x2="${selX.toFixed(1)}" y2="${H-bottom+16}" stroke="var(--accent)" stroke-width="2" pointer-events="none"/><g id="hits">${hits}</g>`;
  $('#riverStage').classList.toggle('hasfocus',!!state.focusTeam);
  const axisYears=era||n<=40?years.slice(i0,i1+1).filter((y,k,arr)=>arr.length<=14||k%Math.ceil(arr.length/12)===0||k===arr.length-1):[years[0]].concat(years.filter(y=>y%20===0&&y-years[0]>=8&&years[years.length-1]-y>=4),[years[years.length-1]]);
  $('#riverAxis').innerHTML=axisYears.map(y=>`<span>${y}</span>`).join('');
  const legend=$('#riverLegend');const scoreOf=era?eraTotal:teamTotal;const topN=[...drawTeams].sort((a,b)=>(scoreOf[b]||0)-(scoreOf[a]||0)).slice(0,14);if(state.focusTeam&&!(scoreOf[state.focusTeam]>0))state.focusTeam=null;
  legend.innerHTML=topN.map(t=>`<button type="button" data-t="${esc(t)}" class="${state.focusTeam===t?'on':''}"><i style="background:${color(t)}"></i>${esc(t)}</button>`).join('');
  if(!legend.dataset.built){legend.dataset.built='1';legend.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;state.focusTeam=state.focusTeam===b.dataset.t?null:b.dataset.t;drawRiver();});}
  const tip=$('#riverTip'),stage=$('#riverStage');
  svg.onmousemove=e=>{const hit=e.target.closest('.yearhit');if(!hit){tip.classList.remove('show');$('#riverCursor').style.opacity=0;return;}const y=+hit.dataset.y,i=years.indexOf(y);const cx=x(i);const cur=$('#riverCursor');cur.setAttribute('x1',cx);cur.setAttribute('x2',cx);cur.style.opacity=1;
    const top5=Object.entries(shares[i]).sort((a,b)=>b[1]-a[1]).slice(0,5);const c=champs[i];
    tip.innerHTML=`<div class="yr">${y}</div><div class="small muted" style="margin:2px 0 8px">${c.races} matches · best record <b style="color:var(--ink)">${esc(c.d||'—')}</b> ${c.rec}${c.cups.map(cp=>` · <b style="color:var(--ink)">${esc(cp.w.join(' & '))}</b> ${esc(cp.label.replace(/^(Men|Women)’s /,''))}`).join('')}</div>${top5.map(([t,p])=>`<div class="row"><span><i class="sw" style="background:${color(t)}"></i>${esc(t)}</span><span>${totals[i]?Math.round(p/totals[i]*100):0}%</span></div>`).join('')}<div class="small dim" style="margin-top:8px">Share of decided matches won that year · click to open</div>`;
    const r=stage.getBoundingClientRect();let px=e.clientX-r.left;px=Math.max(150,Math.min(r.width-150,px));tip.style.left=px+'px';tip.style.top='12px';tip.classList.add('show');};
  svg.onmouseleave=()=>{tip.classList.remove('show');$('#riverCursor').style.opacity=0;};
  svg.onclick=e=>{const b=e.target.closest('.band');const hit=e.target.closest('.yearhit');if(hit){setSeason(+hit.dataset.y,true);}else if(b){state.focusTeam=state.focusTeam===b.dataset.t?null:b.dataset.t;drawRiver();}};
}

/* ---------- the Grounds (the Grid): listed, in the colours of their winners ---------- */
function groundModel(){const ms=eraMatches();const m={};for(const r of ms){if(!r.v||!VENUES[r.v])continue;let c=m[r.v]||(m[r.v]={cid:r.v,count:0,first:r.year,last:r.year,wins:{},name:groundName(r.v),place:VENUES[r.v].city||'',country:'',locationOnly:!!VENUES[r.v].locationOnly});c.count++;c.first=Math.min(c.first,r.year);c.last=Math.max(c.last,r.year);if(r.winner)c.wins[r.winner]=(c.wins[r.winner]||0)+1;}
  return Object.values(m).map(c=>({...c,top:Object.entries(c.wins).sort((a,b)=>b[1]-a[1])[0]?.[0]||null}));}
function drawGrid(){const list=groundModel();const q=state.gridFind.trim().toLowerCase();const unrec=eraMatches().filter(m=>!m.v||!VENUES[m.v]).length;let shown=list.filter(c=>(q||c.count>=state.gridMin)&&(!q||(c.name+' '+c.place).toLowerCase().includes(q)));
  const sorters={count:(a,b)=>b.count-a.count||a.name.localeCompare(b.name),name:(a,b)=>a.name.localeCompare(b.name),country:(a,b)=>a.place.localeCompare(b.place)||b.count-a.count,recent:(a,b)=>b.last-a.last||b.count-a.count};shown.sort(sorters[state.gridSort]);
  const bigN=state.gridSort==='count'&&!q?6:0;const lo=list.filter(c=>c.locationOnly).length;
  $('#gridLede').textContent=`${list.length} grounds have staged an international in ${eraLabel().replace(' · ',', ')}${lo?` (${lo} recorded only as a city)`:''}${unrec?`; ${unrec.toLocaleString('en')} more matches have no ground recorded`:''}. Each carries the colour of the side that has won there most; the largest cards are the grounds the game has returned to most often.${shown.length<list.length&&!q?` Showing ${shown.length} with ${state.gridMin}+ matches.`:''}`;
  $('#circuits').innerHTML=shown.map((c,i)=>`<button type="button" class="circ flat${i<bigN?' big':''}" data-cid="${esc(c.cid)}" style="${c.top?teamVar(c.top):'--team:#8b9099'}" title="${esc(c.name)} · ${c.count} matches · ${c.first}–${c.last}${c.top?' · most wins: '+esc(c.top):''}"><span class="ct">${esc(c.place||'')}${c.locationOnly?' · city only':''}</span><span class="n">${c.count}</span><span class="nm">${esc(c.name)}</span><span class="yrs">${c.first}${c.last!==c.first?'–'+c.last:''}${c.top?' · <i style="background:var(--team)"></i>'+esc(c.top)+' '+c.wins[c.top]:''}</span></button>`).join('')||`<p class="muted">No ground matches.</p>`;}

/* ---------- Stage: tabs, era strip, era context ---------- */
const TABS=[['season','Season'],['match','Match'],['nations','Teams'],['players','Players'],['grounds','Grounds'],['records','Records'],['barcode','Barcode'],['duel','Duel']];
function drawTabs(){$('#tabs').innerHTML=TABS.map(([id,l])=>`<button type="button" role="tab" data-tab="${id}" aria-pressed="${state.tab===id}">${l}</button>`).join('');
  $('#stageStatus').textContent=(state.tab==='season'||state.tab==='match')&&!state.whole?`${state.year} · ${eraOf(state.year)?.name||''} · ${lensLabel()}`:eraLabel();}
function drawEraStrip(preview){const strip=$('#eraStrip');if(!strip.children.length)strip.innerHTML=ERAS.map(e=>`<button type="button" style="--w:${e.to-e.from+1}" data-era="${e.id}" title="${esc(e.name)} · ${e.from}–${e.to}" aria-label="${esc(e.name)} ${e.from}–${e.to}"></button>`).join('');
  for(const b of strip.children){b.classList.toggle('on',state.era===b.dataset.era);b.classList.toggle('demo',preview===b.dataset.era);}
  const e=preview?ERAS.find(x=>x.id===preview):state.era==='all'?eraOf(state.year):ERAS.find(x=>x.id===state.era);
  $('#eraCaption').innerHTML=`<span><b>${esc(e.name)}</b> · ${e.from}–${e.to}</span><span class="dim">${state.era===e.id?'Lens on · click again to release':'Click a segment to focus the whole page on that era'}</span>`;
  const ctx=$('#eraContext');ctx.innerHTML=`<div class="era-car">${e.ball.svg}</div><div><p class="eyebrow">${state.era===e.id?'Era lens':preview?'Era':'Era of the selected season'} · ${e.from}–${e.to}</p><h3>${esc(e.name)}</h3><p>${esc(e.text)}</p><div class="chips">${e.ball.features.map(f=>`<span>${esc(f)}</span>`).join('')}</div><p class="small dim" style="margin:10px 0 0">${esc(e.ball.label)} · an editorial reading of the period; the archive itself is not divided</p></div>`;}
const tour={i:-1,timer:null,visible:false,stopped:RM};
function tourStep(){if(tour.stopped||!tour.visible)return;tour.i=(tour.i+1)%ERAS.length;const ctx=$('#eraContext');ctx.classList.add('swap');setTimeout(()=>{if(tour.stopped)return;drawEraStrip(ERAS[tour.i].id);ctx.classList.remove('swap');},260);tour.timer=setTimeout(tourStep,4200);}
function tourStart(){if(tour.stopped||tour.timer)return;tour.timer=setTimeout(tourStep,1800);}
function tourPause(){clearTimeout(tour.timer);tour.timer=null;}
function tourStop(){if(tour.stopped)return;tour.stopped=true;tourPause();$('#eraContext').classList.remove('swap');drawEraStrip();}

/* ---------- shared pieces ---------- */
const scoreStr=i=>i[5]?'forfeited':`${i[1]}${i[2]<10?'/'+i[2]:''}${i[4]?'d':''}`;
const sides=(m,t)=>{const xs=(m.sc||[]).filter(i=>i[0]===t&&!i[6]);return xs.length?xs.map(scoreStr).join(' & '):'';};
const resultLine=m=>m.nr?'No result':m.result==='tie'?'Tied':m.result==='draw'?'Drawn':m.winner?`${m.winner} won${m.margin?' by '+m.margin:''}`:'—';
const compShort=m=>m.event?m.event.replace(/^ICC /,'').replace(/Men's |Men’s /,'').replace(/^Cricket World Cup$/,'World Cup')+(m.stage&&isNaN(+m.stage)?' · '+m.stage:''):m.f;
function matchCard(m,on){const w=m.winner;return `<button type="button" class="cal${on?' on':''}" data-match="${esc(m.id)}" style="${w?teamVar(w):'--team:#5b616b'}"><div class="rd">${esc(dm(m.date))} · ${esc(m.f)}${m.event?' · '+esc(compShort(m)).slice(0,22):''}</div><div class="sc"><span>${esc(code(m.home))}<small>${esc(sides(m,m.home))}</small></span><b>v</b><span>${esc(code(m.away))}<small>${esc(sides(m,m.away))}</small></span></div><div class="nm">${esc(m.home)} v ${esc(m.away)}</div><div class="w">${esc(resultLine(m))}</div></button>`;}
function natBars(rows,valOf,subOf,max,unit=''){return `<div class="board">${rows.map((a,i)=>`<button type="button" class="bar" data-nation="${esc(a.id)}" style="--i:${i};${teamVar(a.id)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(a.id)}<small> ${a.w}–${a.l}–${a.d}${a.nr?' · '+a.nr+' NR':''}</small></span><small>${subOf(a)}</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*valOf(a)/(max||1))}%"></span></span></span><span class="val">${valOf(a)}${unit}</span></button>`).join('')}</div>`;}
function drawChart(el,series,n,labelOf,xl){const box=el.getBoundingClientRect(),W=Math.max(300,box.width),H=Math.max(200,box.height);const padL=34,padR=110,padT=14,padB=26;const max=Math.max(1,...series.flatMap(s=>s.pts));const x=i=>padL+(n?i*(W-padL-padR)/n:0),y=v=>padT+(H-padT-padB)*(1-v/max);
  let g='';const step=max>200?100:max>60?25:max>20?10:max>8?5:1;for(let v=0;v<=max;v+=step)g+=`<line class="gridl" x1="${padL}" x2="${W-padR}" y1="${y(v).toFixed(1)}" y2="${y(v).toFixed(1)}"/><text class="lb" x="${padL-6}" y="${(y(v)+3).toFixed(1)}" text-anchor="end">${v}</text>`;
  for(let i=0;i<n;i++){const l=xl(i);if(l)g+=`<text class="lb" x="${x(i+1).toFixed(1)}" y="${H-8}" text-anchor="middle">${esc(l)}</text>`;}
  const paths=series.map(s=>{const d=s.pts.map((v,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(v).toFixed(1)).join('');const last=s.pts[s.pts.length-1];return `<path class="ser" d="${d}" style="--c:${color(s.id)}"><title>${esc(labelOf(s.id))} · ${fmt(last)}</title></path><text class="end" x="${(x(n)+6).toFixed(1)}" y="${(y(last)+4).toFixed(1)}" style="--c:${color(s.id)}">${esc(labelOf(s.id))} ${fmt(last)}</text>`;}).join('');
  el.innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Cumulative wins">${g}${paths}</svg>`;}

/* ---------- Season ---------- */
function seasonView(){if(state.whole)return eraView();const s=byYear[state.year];if(!s){$('#view').innerHTML='<p class="muted">No matches in this lens.</p>';return;}const ms=s.matches;const st=natStats(ms);const maxP=Math.max(...st.map(a=>a.p));const ranked=rankRecords(ms,3);const table=[...st].sort(recordOrder);
  const {best,cups}=champOf(s);const partial=String(s.year)===(A.lastDate||'').slice(0,4);const nations=st.length,grounds=new Set(ms.filter(m=>m.recorded).map(m=>m.v)).size;
  const podium=ranked.slice(0,3);const order=[podium[1],podium[0],podium[2]];
  const head=`<div class="season-head"><div class="champ-card" style="${best?`--accent:${color(best.id)};--on-accent:${onColor(color(best.id))}`:''}"><p class="eyebrow" style="color:var(--ink);opacity:.7">${partial?'Season in progress · results through '+esc(day(A.lastDate)):'Best record of the year'} · ${esc(lensLabel())}</p><div class="yr">${s.year}</div>${best?`<div class="who"><small>${partial?'Leads the year':'Best record'} · ${best.w}–${best.l}–${best.d}</small>${esc(best.id)}</div><div class="team"><i></i>${esc(nat(best.id).code)}</div><div class="facts"><div><b>${best.rate}%</b>win rate</div><div><b>${best.p}</b>matches</div><div><b>${ms.length}</b>matches this year</div><div><b>${nations}</b>sides</div></div>`:'<div class="who">No results yet</div>'}${cups.map(c=>`<p class="small" style="margin:14px 0 0;color:var(--ink);opacity:.85">${esc(c.label)}: <b>${esc(c.w.join(' & '))}</b>${c.runner?' · beat '+esc(c.runner):''}${c.note?' · '+esc(c.note):''}</p>`).join('')}<p class="small dim" style="margin:${cups.length?6:18}px 0 0">Ranked by wins minus losses, then win rate, among sides that played a real share of the year (${Math.min(Math.max(3,Math.round(maxP*0.4)),maxP)}+ matches).</p></div>
  <div><div class="podium">${order.map((d,i)=>d?`<button type="button" class="step p${podium.indexOf(d)+1} bar" data-nation="${esc(d.id)}" style="--h:${Math.round(120+120*d.rate/100)}px;${teamVar(d.id)};display:flex"><span class="pos">${podium.indexOf(d)+1}</span><span class="nm">${esc(d.id)}</span><span class="pt">${d.w}–${d.l}–${d.d} · ${d.rate}% · ${d.p} matches</span></button>`:'<div></div>').join('')}<div class="base"></div></div></div></div>`;
  const cal=`<div class="h3"><span>The year’s matches</span><small>${ms.length} matches · click one to open it</small></div><div class="calendar">${ms.map(m=>matchCard(m,state.match===m.id&&state.tab==='match')).join('')}</div>`;
  const big=[...ms].filter(m=>m.marginN&&m.winner).sort((a,b)=>(b.marginN.by==='run')-(a.marginN.by==='run')||b.marginN.n-a.marginN.n).slice(0,10);
  const body=`<div class="two" style="margin-top:26px"><div class="panel"><div class="h3"><span>Table of the year</span><small>every side that played · wins minus losses, then win rate</small></div>${natBars(table,a=>a.rate,a=>`${a.p} matches${a.hi?' · highest total '+a.hi:''}`,100,'%')}</div><div class="panel"><div class="h3"><span>Biggest wins of the year</span><small>by runs, then by wickets</small></div><div class="board">${big.map((m,i)=>`<button type="button" class="bar" data-match="${esc(m.id)}" style="--i:${i};${teamVar(m.winner)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(m.winner)}<small> v ${esc(m.loser)}</small></span><small>${esc(dm(m.date))} · ${esc(m.f)}${m.recorded?' · '+esc(groundName(m.v)):''}</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*(m.marginN.by==='run'?m.marginN.n/(big[0].marginN.by==='run'?big[0].marginN.n:1):m.marginN.n/10))}%"></span></span></span><span class="val">${esc(m.margin)}</span></button>`).join('')||'<p class="muted small">No decided results.</p>'}</div></div></div>
  <div class="panel" style="margin-top:20px"><div class="h3"><span>The year, match by match</span><small>cumulative wins, top ${Math.min(8,st.length)} sides</small></div><div class="chart" id="cumChart"></div></div>`;
  $('#view').innerHTML=head+cal+body;
  const top=[...st].sort((a,b)=>b.w-a.w||b.rate-a.rate).slice(0,8);const series=top.map(a=>({id:a.id,pts:[0]}));for(const m of ms)for(const sr of series)sr.pts.push(sr.pts[sr.pts.length-1]+(m.winner===sr.id?1:0));
  let lastMon='';drawChart($('#cumChart'),series,ms.length,x=>x,i=>{const mon=ms[i].date.slice(5,7);if(mon===lastMon)return '';lastMon=mon;return new Date(ms[i].date+'T12:00:00Z').toLocaleDateString('en-GB',{month:'short',timeZone:'UTC'});});}

/* ---------- Whole era, combined ---------- */
function eraView(){const seasons=eraSeasons();const ms=eraMatches();if(!seasons.length){$('#view').innerHTML='<p class="muted">No matches in this lens.</p>';return;}const e=state.era==='all'?null:ERAS.find(x=>x.id===state.era);const label=e?e.name:'All eras';const span=`${seasons[0].year}–${seasons[seasons.length-1].year}`;
  const st=natStats(ms);const ranked=rankRecords(ms,10);const byWins=[...st].sort((a,b)=>b.w-a.w||b.rate-a.rate);
  const bests={};const roll=seasons.map(s=>{const c=champOf(s);if(c.best)bests[c.best.id]=(bests[c.best.id]||0)+1;return {year:s.year,d:c.best?.id,rec:c.best?`${c.best.w}–${c.best.l}–${c.best.d}`:'',cups:c.cups,n:s.matches.length};});
  const cups=CHAMPS.filter(c=>c.g===state.gender&&inEraYear(c.y)&&(state.fmt==='all'||c.f===state.fmt));const grounds=new Set(ms.filter(m=>m.recorded).map(m=>m.v)).size;
  const podium=ranked.slice(0,3);const order=[podium[1],podium[0],podium[2]];const top=ranked[0];
  const head=`<div class="season-head"><div class="champ-card" style="${top?`--accent:${color(top.id)};--on-accent:${onColor(color(top.id))}`:''}"><p class="eyebrow" style="color:var(--ink);opacity:.7">Whole era, combined · ${seasons.length} seasons · ${esc(lensLabel())}</p><div class="yr" style="font-size:clamp(44px,6vw,84px)">${span}</div><div class="who"><small>${esc(label)} · best record</small>${esc(top?top.id:'—')}</div><div class="team"><i></i>${top?`${top.w}–${top.l}–${top.d} · ${top.rate}% of ${top.p} matches`:''}</div><div class="facts"><div><b>${fmt(ms.length)}</b>matches</div><div><b>${st.length}</b>sides</div><div><b>${grounds}</b>grounds</div><div><b>${cups.length}</b>ICC titles</div></div><p class="small" style="margin:18px 0 0;color:var(--ink);opacity:.85">Most wins: <b>${esc(byWins[0]?.id||'—')}</b> · ${byWins[0]?.w||0} matches won${Object.keys(bests).length?`<br><span class="dim">Best record of the year most often: ${esc(Object.entries(bests).sort((a,b)=>b[1]-a[1])[0][0])} (${Object.entries(bests).sort((a,b)=>b[1]-a[1])[0][1]} years)</span>`:''}</p></div>
  <div><div class="podium">${order.map(d=>d?`<button type="button" class="step p${podium.indexOf(d)+1} bar" data-nation="${esc(d.id)}" style="--h:${Math.round(120+120*d.rate/100)}px;${teamVar(d.id)};display:flex"><span class="pos">${podium.indexOf(d)+1}</span><span class="nm">${esc(d.id)}</span><span class="pt">${d.rate}% · ${d.w}–${d.l}–${d.d}</span></button>`:'<div></div>').join('')}<div class="base"></div></div></div></div>`;
  const rollHtml=`<div class="h3"><span>Best record, year by year</span><small>click a year to open it</small></div><div class="calendar">${roll.map(c=>`<button type="button" class="cal" data-year="${c.year}" style="${c.d?teamVar(c.d):'--team:#5b616b'}"><div class="rd">${c.year} · ${c.n} matches</div><div class="nm" style="font-size:16px;margin-top:10px;color:var(--team)">${esc(c.d||'—')}</div><div class="w" style="color:var(--muted)">${c.rec}</div><div class="w">${c.cups.map(cp=>'⚑ '+esc(cp.w.join(' & '))).join(' ')}</div></button>`).join('')}</div>`;
  const pl=playerAgg().sort((a,b)=>b.runs-a.runs).slice(0,20);
  const body=`<div class="two" style="margin-top:26px"><div class="panel"><div class="h3"><span>Sides across the era</span><small>by wins · ${st.length} sides</small></div>${natBars(byWins.slice(0,20),a=>a.w,a=>`${a.rate}% of ${a.p} matches`,byWins[0]?.w)}</div><div class="panel"><div class="h3"><span>Run-scorers across the era</span><small>recorded player-season figures</small></div><div class="board">${pl.map((p,i)=>`<button type="button" class="bar" data-player="${esc(p.id)}" style="--i:${i};${teamVar(p.team)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(pname(p.id))}<small> ${esc(p.team)}</small></span><small>${p.games} matches · ${p.hundreds} hundreds</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*p.runs/(pl[0]?.runs||1))}%"></span></span></span><span class="val">${fmt(p.runs)}</span></button>`).join('')||'<p class="muted small">No player figures in this lens.</p>'}</div></div></div>
  <div class="panel" style="margin-top:20px"><div class="h3"><span>Wins, season by season</span><small>cumulative wins, top ${Math.min(8,byWins.length)} by wins</small></div><div class="chart" id="cumChart"></div></div>`;
  $('#view').innerHTML=head+rollHtml+body;
  const series=byWins.slice(0,8).map(a=>({id:a.id,pts:[0]}));for(const s of seasons)for(const sr of series){let w=0;for(const m of s.matches)if(m.winner===sr.id)w++;sr.pts.push(sr.pts[sr.pts.length-1]+w);}
  drawChart($('#cumChart'),series,seasons.length,x=>x,i=>seasons.length<=20||i%Math.ceil(seasons.length/14)===0?String(seasons[i].year).slice(2):'');}
function eraMatchesView(){const ms=eraMatches();$('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Every match · ${esc(eraLabel())}</span><small>${fmt(ms.length)} matches · click one to open it</small></div><div class="tablewrap"><table><tr><th>Date</th><th>Format</th><th>Sides</th><th>Scores</th><th>Result</th><th>Ground</th></tr>${ms.slice().reverse().slice(0,1200).map(m=>`<tr><td><a href="#" data-match="${esc(m.id)}" style="color:inherit">${esc(day(m.date))}</a></td><td>${esc(m.f)}</td><td><i class="dot" style="${teamVar(m.home)}"></i>${esc(m.home)} v <i class="dot" style="${teamVar(m.away)}"></i>${esc(m.away)}</td><td>${esc(sides(m,m.home))}${sides(m,m.home)&&sides(m,m.away)?' · ':''}${esc(sides(m,m.away))}</td><td>${esc(resultLine(m))}</td><td>${m.v&&VENUES[m.v]?`<a href="#" data-ground="${esc(m.v)}" style="color:inherit">${esc(groundName(m.v))}</a>`:'<span class="dim">not recorded</span>'}</td></tr>`).join('')}</table></div>${ms.length>1200?`<p class="small dim">Showing the most recent 1,200 of ${fmt(ms.length)}; narrow the lens or open a season for the rest.</p>`:''}`;}

/* ---------- Match: the sheet, the scorecards and the innings replay ---------- */
let replay=null;
function stopReplay(){if(replay){cancelAnimationFrame(replay.raf);replay=null;}}
const detailOf=m=>DETAILS[m.year]?.[m.id]||null;
let loading={};
function loadDetails(year){if(DETAILS[year]||!DETAIL_URL||loading[year])return Promise.resolve();loading[year]=true;return fetch(`${DETAIL_URL}${year}.json`).then(r=>r.ok?r.json():{}).then(j=>{DETAILS[year]=j||{};}).catch(()=>{DETAILS[year]={};}).finally(()=>{loading[year]=false;});}
const overs=b=>`${Math.floor(b/6)}.${b%6}`;
function dismissal(ba){const kind=ba[5],bowler=ba[6]?pname(ba[6]):'',fs=(ba[7]||[]).map(pname).join(' / ');if(kind==='caught')return 'c '+(fs||'fielder not recorded')+' b '+bowler;if(kind==='caught and bowled')return 'c & b '+bowler;if(kind==='stumped')return 'st '+(fs||'keeper not recorded')+' b '+bowler;if(kind==='bowled')return 'b '+bowler;if(kind==='lbw')return 'lbw b '+bowler;if(kind==='run out')return 'run out'+(fs?' ('+fs+')':'');if(kind==='not out')return 'not out';return kind||'—';}
function inningsCard(i,k){const os=i[10]||[];const bat=(i[8]||[]).map(b=>`<tr><td><a href="#" data-player="${esc(b[0])}" style="color:inherit">${esc(pname(b[0]))}</a></td><td class="dim">${esc(dismissal(b))}</td><td><b>${b[1]}${['not out','retired hurt','retired not out'].includes(b[5])?'*':''}</b></td><td>${b[2]}</td><td>${b[3]}</td><td>${b[4]}</td><td>${b[2]?(100*b[1]/b[2]).toFixed(0):'—'}</td></tr>`).join('');
  const bowl=(i[9]||[]).map(b=>`<tr><td><a href="#" data-player="${esc(b[0])}" style="color:inherit">${esc(pname(b[0]))}</a></td><td>${overs(b[1])}</td><td>${b[4]}</td><td>${b[2]}</td><td><b>${b[3]}</b></td><td>${b[1]?(6*b[2]/b[1]).toFixed(2):'—'}</td></tr>`).join('');
  const ex=i[7]||[0,0,0,0,0];
  return `<details class="inn"${k===0?' open':''}><summary><span class="eyebrow" style="margin:0">${i[6]?'Super Over':'Innings '+(k+1)}</span><b style="${teamVar(i[0])}"><i class="dot" style="${teamVar(i[0])}"></i>${esc(i[0])}</b><span class="tot">${esc(scoreStr(i))}</span><span class="dim">${overs(i[3])} overs${i[12]?' · target '+i[12]:''}</span></summary>
  ${os.length?`<div class="worm" data-k="${k}"><svg viewBox="0 0 900 220" class="wormsvg" role="img" aria-label="Runs by over"></svg><div class="wormscore"><b class="r">0</b><span class="dim">for</span><b class="w">0</b><span class="dim ov">over 0 of ${os.length}</span></div></div>`:''}
  <div class="sheet"><div><div class="h3"><span>Batting</span></div><div class="tablewrap" style="max-height:none"><table><tr><th>Batter</th><th></th><th>R</th><th>B</th><th>4s</th><th>6s</th><th>SR</th></tr>${bat}</table></div><p class="small dim" style="margin:6px 0 0">Extras ${ex.reduce((a,b)=>a+b,0)} · wides ${ex[0]} · no-balls ${ex[1]} · byes ${ex[2]} · leg-byes ${ex[3]}${ex[4]?' · penalties '+ex[4]:''}</p></div><div><div class="h3"><span>Bowling</span></div><div class="tablewrap" style="max-height:none"><table><tr><th>Bowler</th><th>O</th><th>M</th><th>R</th><th>W</th><th>Econ</th></tr>${bowl}</table></div>${(i[11]||[]).length?`<p class="small dim" style="margin:8px 0 0">Fall of wickets: ${i[11].map(w=>`${w[0]}/${w[1]} (${esc(pname(w[3]))}, ${esc(w[2])})`).join(' · ')}</p>`:''}</div></div></details>`;}
function matchView(){if(state.whole)return eraMatchesView();const s=byYear[state.year];if(!s){$('#view').innerHTML='<p class="muted">No matches in this lens.</p>';return;}let m=byId[state.match];if(!m||m.year!==s.year||!inLens(m))m=s.matches[s.matches.length-1];state.match=m.id;
  const many=s.matches.length>36;const nav=`<div class="chiplist${many?' many':''}" id="matchNav" style="margin-top:20px">${s.matches.map(x=>`<button type="button" class="chip${x.id===m.id?' on':''}" data-match="${esc(x.id)}" style="${x.id===m.id?'border-color:var(--accent);color:var(--accent)':''}"><i style="--c:${x.winner?color(x.winner):'#444'}"></i>${esc(dm(x.date))} ${esc(code(x.home))}–${esc(code(x.away))}</button>`).join('')}</div>`;
  const d=detailOf(m);const inn=d?d.inn||[]:[];
  const hero=`<div class="replay" id="replay"><div class="hud"><div><h3>${esc(m.home)} v ${esc(m.away)}</h3><div class="sub">${esc(day(m.date))}${m.end&&m.end!==m.date?' – '+esc(dm(m.end)):''} · ${esc(m.f)}${m.event?' · '+esc(m.event):''}${m.stage&&isNaN(+m.stage)?' · '+esc(m.stage):''}${m.recorded?' · '+esc(groundName(m.v)):''}</div></div><div class="whistle">${m.nr?'NR':m.draw?(m.result==='tie'?'TIE':'DRAW'):'RESULT'}</div></div>
  <div class="scoreboard">${m.teams.map(t=>`<div class="sb" style="${teamVar(t)}"><span class="tn"><i class="dot" style="${teamVar(t)}"></i>${esc(t)}</span><b>${esc(sides(m,t)||'—')}</b></div>`).join('')}</div><p class="result">${esc(resultLine(m))}${m.method?' · '+esc(m.method):''}</p>
  ${inn.length?inn.map((i,k)=>inningsCard(i,k)).join(''):d?'<p class="small dim">No scorecard is held for this match.</p>':(DETAIL_URL&&m.detail?'<p class="small dim" id="detailWait">Fetching the scorecard…</p>':'<p class="small dim">This record carries the result, date and ground; no scorecard is recorded in the source.'+(m.rawDate?' Original date listing: '+esc(m.rawDate)+'.':'')+'</p>')}
  ${inn.some(i=>(i[10]||[]).length)?'<p class="small dim" style="margin:10px 0 0">The worm builds the innings over by over from the recorded deliveries: a symbolic replay of the scoring, not a broadcast.</p>':''}</div>`;
  const hh=h2hBefore(m);const form=side=>{const prev=MATCHES.filter(x=>x.date<m.date&&x.g===m.g&&(state.fmt==='all'||x.f===state.fmt)&&x.teams.includes(side)).slice(-10);return `<div class="ribbon">${prev.map(x=>`<i class="${resClass(x,side)}" title="${esc(day(x.date))} v ${esc(x.home===side?x.away:x.home)} · ${esc(resultLine(x))}" data-match="${esc(x.id)}"></i>`).join('')}</div>`;};
  const lineups=d&&d.players&&d.players.length?`<div class="h3" style="margin-top:20px"><span>Line-ups</span></div><div class="two" style="gap:14px">${d.players.map(([t,ids])=>`<div><p class="eyebrow" style="margin:0 0 6px">${esc(t)}</p><div class="chiplist">${ids.map(id=>`<button type="button" class="chip" data-player="${esc(id)}"><i style="--c:${color(t)}"></i>${esc(pname(id))}${(m.pom||[]).includes(id)?' ★':''}</button>`).join('')}</div></div>`).join('')}</div>`:'';
  const side=`<div><div class="h3"><span>Before the toss</span><small>the record between these two, ${esc(m.f)}</small></div><div class="kpis" style="grid-template-columns:1fr 1fr"><div class="kpi" style="border-color:${color(m.home)}"><span>${esc(m.home)}</span><b>${hh.a?hh.a.w:0}</b><small>wins in ${hh.n} previous ${m.f} meetings</small>${form(m.home)}</div><div class="kpi" style="border-color:${color(m.away)}"><span>${esc(m.away)}</span><b>${hh.b?hh.b.w:0}</b><small>wins in ${hh.n} previous meetings${hh.a&&hh.a.d?' · '+hh.a.d+' drawn or tied':''}</small>${form(m.away)}</div></div><p class="small dim" style="margin:8px 0 0">Each side’s last ten matches in this lens: green won, red lost, grey drawn or tied, dark no result.</p>${lineups}
  <div class="kpis" style="margin-top:18px"><div class="kpi"><span>Toss</span><b style="font-size:20px">${m.toss&&m.toss[0]?esc(m.toss[0])+' · '+esc(m.toss[1]):'—'}</b><small>${m.toss&&m.toss[0]?'chose to '+esc(m.toss[1]):'not recorded'}</small></div><div class="kpi"><span>Player of the match</span><b style="font-size:20px">${(m.pom||[]).length?m.pom.map(id=>`<a href="#" data-player="${esc(id)}" style="color:inherit;text-decoration:none">${esc(pname(id))}</a>`).join(' / '):'—'}</b></div><div class="kpi"><span>Ground</span><b style="font-size:20px">${m.v&&VENUES[m.v]?`<a href="#" data-ground="${esc(m.v)}" style="color:inherit;text-decoration:none">${esc(groundName(m.v))}</a>`:'Not recorded'}</b><small>${esc(VENUES[m.v]?.city||'')}</small></div><div class="kpi"><span>Match no.</span><b style="font-size:20px">${m.no?esc(m.f)+' #'+m.no:'—'}</b><small>${esc(m.source==='cricsheet'?'Cricsheet scorecard':'historical results dataset')}</small></div></div></div>`;
  $('#view').innerHTML=`${nav}<div class="race">${hero}${side}</div>`;
  {const on=$('#matchNav .chip.on');if(on&&many){const nv=$('#matchNav');nv.scrollTop=Math.max(0,on.offsetTop-nv.clientHeight/2+on.offsetHeight/2);}}
  if(inn.length)runWorms();else if(DETAIL_URL&&m.detail&&!d){loadDetails(m.year).then(()=>{if(state.tab==='match'&&state.match===m.id)render();});}}
function runWorms(){stopReplay();const worms=$$('.worm');if(!worms.length)return;const m=byId[state.match];const d=detailOf(m);const rp={raf:0,t:0,last:0,dur:RM?1:9000,items:[]};replay=rp;
  for(const el of worms){const i=d.inn[+el.dataset.k];const os=i[10];const cum=[0],wk=[0];for(const o of os){cum.push(cum[cum.length-1]+o[1]);wk.push(wk[wk.length-1]+o[2]);}const max=Math.max(1,...cum);const W=900,H=220,pl=36,pr=20,pt=16,pb=30;const x=j=>pl+(W-pl-pr)*j/os.length,y=r=>pt+(H-pt-pb)*(1-r/max);
    const svg=el.querySelector('svg');const grid=[0,.25,.5,.75,1].map(f=>`<line class="gridl" x1="${pl}" x2="${W-pr}" y1="${y(max*f).toFixed(1)}" y2="${y(max*f).toFixed(1)}"/><text class="lb" x="${pl-6}" y="${(y(max*f)+3).toFixed(1)}" text-anchor="end">${Math.round(max*f)}</text>`).join('');
    const full=cum.map((r,j)=>(j?'L':'M')+x(j).toFixed(1)+' '+y(r).toFixed(1)).join('');const ovs=os.filter((o,j)=>os.length<=20||j%5===4).map(o=>`<text class="lb" x="${x(o[0]+1).toFixed(1)}" y="${H-10}" text-anchor="middle">${o[0]+1}</text>`).join('');
    svg.innerHTML=`${grid}${ovs}<path class="ghost" d="${full}"/><path class="live" d="" style="--c:${color(i[0])}"/><g class="wkts"></g><circle class="head" r="5" style="--c:${color(i[0])}"/>`;
    rp.items.push({el,i,os,cum,wk,x,y,live:svg.querySelector('.live'),head:svg.querySelector('.head'),wg:svg.querySelector('.wkts'),r:el.querySelector('.r'),w:el.querySelector('.w'),ov:el.querySelector('.ov')});}
  const place=t=>{for(const it of rp.items){const n=Math.min(it.os.length,Math.floor(t*it.os.length+1e-9));const d=it.cum.slice(0,n+1).map((r,j)=>(j?'L':'M')+it.x(j).toFixed(1)+' '+it.y(r).toFixed(1)).join('');it.live.setAttribute('d',d);it.head.setAttribute('cx',it.x(n).toFixed(1));it.head.setAttribute('cy',it.y(it.cum[n]).toFixed(1));it.r.textContent=it.cum[n];it.w.textContent=it.wk[n];it.ov.textContent=`over ${n} of ${it.os.length}`;
      let marks='';for(let j=1;j<=n;j++)if(it.os[j-1][2])marks+=`<circle cx="${it.x(j).toFixed(1)}" cy="${it.y(it.cum[j]).toFixed(1)}" r="3.5" class="wk"><title>${it.os[j-1][2]} wicket${it.os[j-1][2]>1?'s':''} in over ${j}</title></circle>`;it.wg.innerHTML=marks;}};
  const tick=now=>{if(replay!==rp)return;if(rp.last)rp.t=Math.min(1,rp.t+(now-rp.last)/rp.dur);rp.last=now;place(rp.t);if(rp.t<1)rp.raf=requestAnimationFrame(tick);else $('#replay').classList.add('done');};
  place(0);rp.raf=requestAnimationFrame(tick);
  for(const it of rp.items){it.el.onclick=()=>{rp.t=0;rp.last=0;$('#replay').classList.remove('done');if(replay!==rp){replay=rp;}cancelAnimationFrame(rp.raf);rp.raf=requestAnimationFrame(tick);};}}
function h2hBefore(m){const ms=MATCHES.filter(x=>x.date<m.date&&x.g===m.g&&x.f===m.f&&x.teams.includes(m.home)&&x.teams.includes(m.away));const st=natStats(ms);const a=st.find(x=>x.id===m.home),b=st.find(x=>x.id===m.away);return {n:ms.length,a,b};}

/* ---------- Teams (nations) ---------- */
function radar(el,axes,a,b){const W=260,H=260,cx=130,cy=130,R=96,n=axes.length;const pt=(i,v)=>{const ang=-Math.PI/2+i*2*Math.PI/n;return [cx+Math.cos(ang)*R*v,cy+Math.sin(ang)*R*v];};
  let g='';for(const k of [.25,.5,.75,1])g+=`<polygon class="ring" points="${axes.map((_,i)=>pt(i,k).map(v=>v.toFixed(1)).join(',')).join(' ')}"/>`;for(let i=0;i<n;i++){const [x,y]=pt(i,1);g+=`<line class="axis" x1="${cx}" y1="${cy}" x2="${x.toFixed(1)}" y2="${y.toFixed(1)}"/>`;const [lx,ly]=pt(i,1.24);g+=`<text class="lbl" x="${lx.toFixed(1)}" y="${(ly+3).toFixed(1)}">${esc(axes[i].label)}</text>`;}
  const poly=(vals,cls)=>`<polygon class="poly ${cls}" points="${vals.map((v,i)=>pt(i,Math.max(0,Math.min(1,v))).map(q=>q.toFixed(1)).join(',')).join(' ')}"/>`;el.innerHTML=`<svg viewBox="0 0 ${W} ${H}">${g}${poly(a,'a')}${b?poly(b,'b'):''}</svg>`;}
const AXES=[{k:'w',label:'Wins'},{k:'rate',label:'Win %'},{k:'p',label:'Matches'},{k:'hi',label:'Top total'},{k:'streak',label:'Best run'},{k:'cups',label:'Titles'}];
function normAxes(list){const max={};for(const ax of AXES)max[ax.k]=Math.max(1,...list.map(a=>a[ax.k]));return a=>AXES.map(ax=>a[ax.k]/max[ax.k]);}
function nationsView(){const ms=eraMatches();const list=natStats(ms);const lens=state.lens;const min=/rate/.test(lens)?10:0;const rows=list.filter(a=>a.p>=min).sort((a,b)=>b[lens]-a[lens]||b.w-a.w).slice(0,40);const max=Math.max(1,...rows.map(a=>a[lens]));const q=(state.find2||'').toLowerCase();const found=q?list.filter(a=>a.id.toLowerCase().includes(q)).slice(0,12):[];
  $('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Teams · ${esc(eraLabel())}</span><small>${list.length} sides · ${fmt(ms.length)} matches</small></div><div class="panel"><div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:14px"><input type="search" id="find2" placeholder="Search a team" value="${esc(state.find2||'')}" aria-label="Search"><select id="lens" aria-label="Lens">${Object.entries(LENSES).map(([k,v])=>`<option value="${k}" ${k===lens?'selected':''}>${v[0]}</option>`).join('')}</select><span class="small muted">${esc(LENSES[lens][1])}</span></div>${q?`<div class="chiplist" style="margin-bottom:14px">${found.map(a=>`<button type="button" class="chip" data-nation="${esc(a.id)}"><i style="--c:${color(a.id)}"></i>${esc(a.id)}</button>`).join('')||'<span class="muted small">No match.</span>'}</div>`:''}
  ${natBars(rows,a=>a[lens],a=>`${a.p} matches · ${a.first}–${a.last}`,max,/rate/.test(lens)?'%':'')}</div>`;}
function seasonsTable(id){const out=[];for(const s of S){const ms=s.matches.filter(m=>m.teams.includes(id));if(!ms.length)continue;const a=natStats(ms).find(x=>x.id===id);out.push({year:s.year,...a});}return out;}
function nationView(id){const ms=eraMatches();const all=natStats(ms);const a=all.find(x=>x.id===id);const back=`<button type="button" class="btn" data-tab="nations">← All teams</button>`;const t=nat(id);
  if(!a){$('#view').innerHTML=`<div style="margin-top:22px">${back}</div><p class="muted" style="margin-top:16px">${esc(id)} played no match in ${esc(eraLabel())}. Change the lens to see them.</p>`;return;}
  const mine=ms.filter(m=>m.teams.includes(id));const norm=normAxes(all.filter(x=>x.p>=10));
  const ribbon=mine.map(m=>`<i class="${resClass(m,id)}" title="${esc(day(m.date))} v ${esc(m.home===id?m.away:m.home)} · ${esc(resultLine(m))}" data-match="${esc(m.id)}"></i>`).join('');
  const opp={};for(const m of mine){const o=m.home===id?m.away:m.home;let r=opp[o]||(opp[o]={id:o,p:0,w:0,d:0,l:0,nr:0});r.p++;const rc=resClass(m,id);if(rc==='W')r.w++;else if(rc==='L')r.l++;else if(rc==='D')r.d++;else r.nr++;}const opps=Object.values(opp).sort((a,b)=>b.p-a.p);
  const tbl=seasonsTable(id).filter(x=>inEraYear(x.year));const cups=CHAMPS.filter(c=>c.g===state.gender&&inEraYear(c.y)&&(state.fmt==='all'||c.f===state.fmt)&&(c.w.includes(id)||c.runner===id));
  const players=playerAgg().filter(p=>p.team===id).sort((a,b)=>b.runs-a.runs).slice(0,8);const bowlers=playerAgg().filter(p=>p.team===id).sort((a,b)=>b.wickets-a.wickets).slice(0,8);
  $('#view').innerHTML=`<div style="margin-top:22px;display:flex;gap:10px;flex-wrap:wrap;align-items:center">${back}<span class="small muted">${esc(eraLabel())}</span></div>
  <div class="card" style="margin-top:18px;${teamVar(id)}"><div class="panel"><div class="trace" id="trace"></div><p class="small dim" style="text-align:center;margin:8px 0 0">Form trace · each axis relative to the best side in this lens (10+ matches)</p></div>
  <div><p class="eyebrow">${t.major?'Full member':'Side'} · ${a.first}–${a.last} · ${esc(t.code)}</p><h2 class="display" style="font-size:clamp(40px,6vw,84px);margin:6px 0 0;color:var(--team);text-shadow:0 0 30px rgba(255,255,255,.18)">${esc(id)}</h2>
  <div class="kpis" style="margin-top:18px"><div class="kpi"><span>Matches</span><b>${a.p}</b><small>${a.w}–${a.l}–${a.d}${a.nr?' · '+a.nr+' no result':''}</small></div><div class="kpi"><span>Win rate</span><b>${a.rate}%</b><small>draws and no-results count as not won</small></div>${FORMATS.filter(f=>a.byF[f]).map(f=>`<div class="kpi"><span>${f}</span><b>${a.byF[f].w}–${a.byF[f].l}–${a.byF[f].d}</b><small>${a.byF[f].p} matches · ${pct(a.byF[f].w,a.byF[f].p)}%</small></div>`).join('')}<div class="kpi"><span>Best run</span><b>${a.streak}</b><small>consecutive wins</small></div><div class="kpi"><span>ICC titles</span><b>${a.cups}</b><small>${cups.filter(c=>c.w.includes(id)).map(c=>c.y).join(', ')||'in lens'}</small></div>${a.hi?`<div class="kpi"><span>Highest total</span><b>${a.hi}</b><small>recorded scorecards</small></div>`:''}</div>
  <div class="h3" style="margin-top:20px"><span>Every match</span><small>green won · red lost · grey drawn or tied · dark no result · click to open</small></div><div class="ribbon">${ribbon}</div></div></div>
  <div class="two" style="margin-top:20px"><div class="panel"><div class="h3"><span>Record by opponent</span><small>most met first</small></div>${natBars(opps.slice(0,16),r=>r.w,r=>`${r.p} matches · ${pct(r.w,r.p)}% won`,Math.max(1,...opps.map(r=>r.w)))}</div><div class="panel">${players.length?`<div class="h3"><span>Run-scorers</span><small>recorded figures in the lens</small></div><div class="board">${players.map((p,i)=>`<button type="button" class="bar" data-player="${esc(p.id)}" style="--i:${i};${teamVar(id)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(pname(p.id))}<small> ${p.games} matches</small></span><small>${p.hundreds} hundreds · avg ${p.batavg!=null?p.batavg.toFixed(1):'—'}</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*p.runs/(players[0].runs||1))}%"></span></span></span><span class="val">${fmt(p.runs)}</span></button>`).join('')}</div><div class="h3" style="margin-top:16px"><span>Wicket-takers</span></div><div class="board">${bowlers.map((p,i)=>`<button type="button" class="bar" data-player="${esc(p.id)}" style="--i:${i};${teamVar(id)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(pname(p.id))}<small> ${p.games} matches</small></span><small>avg ${p.bowlavg!=null?p.bowlavg.toFixed(1):'—'}${p.five?' · '+p.five+' five-fors':''}</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*p.wickets/(bowlers[0].wickets||1))}%"></span></span></span><span class="val">${fmt(p.wickets)}</span></button>`).join('')}</div>`:'<p class="muted small">No recorded player figures in this lens.</p>'}${cups.length?`<div class="h3" style="margin-top:16px"><span>ICC tournaments</span></div><div class="tablewrap"><table><tr><th>Year</th><th>Tournament</th><th>Outcome</th></tr>${cups.map(c=>`<tr><td>${c.y}</td><td>${esc(c.label)}</td><td>${c.w.includes(id)?'<b style="color:var(--gold)">Champions ★</b>':'Runners-up'}${c.note?' · '+esc(c.note):''}</td></tr>`).join('')}</table></div>`:''}</div></div>
  <div class="panel" style="margin-top:20px"><div class="h3"><span>Season by season</span></div><div class="tablewrap"><table><tr><th>Year</th><th>P</th><th>W</th><th>L</th><th>D/T</th><th>NR</th><th>Win %</th><th>Biggest win</th></tr>${tbl.slice().reverse().map(x=>`<tr><td><a href="#" data-year="${x.year}" style="color:inherit">${x.year}</a></td><td>${x.p}</td><td>${x.w}</td><td>${x.l}</td><td>${x.d}</td><td>${x.nr}</td><td>${x.rate}%</td><td>${x.big?`<a href="#" data-match="${esc(x.big.id)}" style="color:inherit">by ${esc(x.big.margin)} v ${esc(x.big.home===id?x.big.away:x.big.home)}</a>`:'—'}</td></tr>`).join('')}</table></div></div>`;
  radar($('#trace'),AXES,norm(a));}

/* ---------- Players (recorded player-season figures) ---------- */
let aggCache={};
function playerAgg(){const key=[state.gender,state.fmt,state.era].join('|');if(aggCache[key])return aggCache[key];const [y0,y1]=eraRange();const map={};
  for(const r of PS){if(r.g!==state.gender||(state.fmt!=='all'&&r.f!==state.fmt)||r.y<y0||r.y>y1)continue;let a=map[r.p]||(map[r.p]={id:r.p,teams:{},games:0,inns:0,runs:0,balls:0,outs:0,notouts:0,fours:0,sixes:0,fifties:0,hundreds:0,binns:0,bballs:0,conceded:0,wickets:0,maidens:0,five:0,catches:0,stumps:0,runouts:0,pom:0,hs:0,hsno:false,bbw:0,bbr:0,first:r.y,last:r.y});
    for(const k of ['games','inns','runs','balls','outs','notouts','fours','sixes','fifties','hundreds','binns','bballs','conceded','wickets','maidens','five','catches','stumps','runouts','pom'])a[k]+=r[k]||0;
    if(r.hs>a.hs||(r.hs===a.hs&&r.hsno)){a.hs=r.hs;a.hsno=!!r.hsno;}if(r.bbw>a.bbw||(r.bbw===a.bbw&&r.bbw&&r.bbr<a.bbr)){a.bbw=r.bbw;a.bbr=r.bbr;}
    a.teams[r.t]=(a.teams[r.t]||0)+r.games;a.first=Math.min(a.first,r.y);a.last=Math.max(a.last,r.y);}
  const out=Object.values(map).map(a=>({...a,team:Object.entries(a.teams).sort((x,y)=>y[1]-x[1])[0][0],batavg:a.outs?a.runs/a.outs:null,bowlavg:a.wickets?a.conceded/a.wickets:null,sr:a.balls?100*a.runs/a.balls:null,econ:a.bballs?6*a.conceded/a.bballs:null}));
  return aggCache[key]=out;}
function playersView(){const list=playerAgg();const lens=state.plens;let rows=list.filter(p=>p[lens]!=null);if(lens==='batavg')rows=rows.filter(p=>p.inns>=20);if(lens==='bowlavg')rows=rows.filter(p=>p.wickets>=20);rows.sort(lens==='bowlavg'?(a,b)=>a[lens]-b[lens]:(a,b)=>b[lens]-a[lens]||b.games-a.games);rows=rows.slice(0,40);const max=Math.max(1,...rows.map(p=>p[lens]));const q=(state.find2||'').toLowerCase();const found=q?Object.entries(PLAYERS).filter(([id,p])=>p.n.toLowerCase().includes(q)).slice(0,12):[];
  $('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Players · ${esc(eraLabel())}</span><small>${fmt(list.length)} with recorded figures</small></div><div class="panel"><div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:14px"><input type="search" id="find2" placeholder="Search a player" value="${esc(state.find2||'')}" aria-label="Search"><select id="plens" aria-label="Lens">${Object.entries(PLENSES).map(([k,v])=>`<option value="${k}" ${k===lens?'selected':''}>${v[0]}</option>`).join('')}</select><span class="small muted">${esc(PLENSES[lens][1])} Figures come from recorded scorecards (from 2001 for Tests and ODIs, 2005 for T20Is) and are not complete careers.</span></div>${q?`<div class="chiplist" style="margin-bottom:14px">${found.map(([id,p])=>`<button type="button" class="chip" data-player="${esc(id)}"><i style="--c:${color((p.teams||[])[0]||'')}"></i>${esc(p.n)} <span class="dim">${esc((p.teams||[]).join(' / '))}</span></button>`).join('')||'<span class="muted small">No match.</span>'}</div>`:''}
  <div class="board">${rows.map((p,i)=>`<button type="button" class="bar" data-player="${esc(p.id)}" style="--i:${i};${teamVar(p.team)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(pname(p.id))}<small> ${esc(p.team)}</small></span><small>${p.first}–${p.last} · ${p.games} matches · ${fmt(p.runs)} runs · ${p.wickets} wkts</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*(lens==='bowlavg'?(rows[0][lens]/p[lens]):p[lens]/max))}%"></span></span></span><span class="val">${/avg/.test(lens)?p[lens].toFixed(2):fmt(p[lens])}</span></button>`).join('')}</div></div>`;}
function playerView(id){const p=PLAYERS[id];const back=`<button type="button" class="btn" data-tab="players">← All players</button>`;if(!p){$('#view').innerHTML=`<div style="margin-top:22px">${back}</div>`;return;}
  const rows=PS.filter(r=>r.p===id).sort((a,b)=>a.y-b.y||FORMATS.indexOf(a.f)-FORMATS.indexOf(b.f));const inl=rows.filter(r=>r.g===state.gender&&(state.fmt==='all'||r.f===state.fmt)&&inEraYear(r.y));const use=inl.length?inl:rows;const a=playerAgg().find(x=>x.id===id)||aggOf(use);
  const byF=FORMATS.map(f=>{const rr=use.filter(r=>r.f===f);return rr.length?{f,...aggOf(rr)}:null;}).filter(Boolean);
  const team=(p.teams||[])[0]||a.team;const games=MATCHES.filter(m=>(m.pom||[]).includes(id));
  $('#view').innerHTML=`<div style="margin-top:22px;display:flex;gap:10px;flex-wrap:wrap;align-items:center">${back}<span class="small muted">${esc(eraLabel())}</span></div>
  <div class="card" style="margin-top:18px;grid-template-columns:1fr;${teamVar(team)}"><div><p class="eyebrow">Player · ${(p.teams||[]).map(t=>`<a href="#" data-nation="${esc(t)}" style="color:inherit">${esc(t)}</a>`).join(' / ')} · ${a.first}–${a.last}</p><h2 class="display" style="font-size:clamp(40px,6vw,84px);margin:6px 0 0;color:var(--team);text-shadow:0 0 30px rgba(255,255,255,.18)">${esc(p.n)}</h2><p class="muted" style="margin:4px 0 0">${esc(p.short||'')}${p.gender?' · '+(p.gender.includes('W')?'women’s':'men’s')+' internationals':''} · recorded figures ${inl.length?'in this lens':'across all lenses (none in the current lens)'}</p>
  <div class="kpis" style="margin-top:18px"><div class="kpi"><span>Matches</span><b>${a.games}</b><small>${a.inns} batting · ${a.binns} bowling innings</small></div><div class="kpi"><span>Runs</span><b>${fmt(a.runs)}</b><small>avg ${a.batavg!=null?a.batavg.toFixed(2):'—'} · SR ${a.sr!=null?a.sr.toFixed(1):'—'}</small></div><div class="kpi"><span>Highest</span><b>${a.hs}${a.hsno?'*':''}</b><small>${a.hundreds} hundreds · ${a.fifties} fifties</small></div><div class="kpi"><span>Wickets</span><b>${a.wickets}</b><small>avg ${a.bowlavg!=null?a.bowlavg.toFixed(2):'—'} · econ ${a.econ!=null?a.econ.toFixed(2):'—'}</small></div><div class="kpi"><span>Best bowling</span><b>${a.bbw?a.bbw+'/'+a.bbr:'—'}</b><small>${a.five} five-fors</small></div><div class="kpi"><span>Fielding</span><b>${a.catches+a.stumps}</b><small>${a.catches} catches · ${a.stumps} stumpings</small></div><div class="kpi"><span>Player of the match</span><b>${a.pom}</b></div></div>
  ${byF.length>1?`<div class="h3" style="margin-top:20px"><span>By format</span></div><div class="tablewrap"><table><tr><th>Format</th><th>M</th><th>Runs</th><th>Avg</th><th>SR</th><th>HS</th><th>100/50</th><th>Wkts</th><th>Avg</th><th>Econ</th><th>BB</th></tr>${byF.map(x=>`<tr><td>${x.f}</td><td>${x.games}</td><td>${fmt(x.runs)}</td><td>${x.batavg!=null?x.batavg.toFixed(2):'—'}</td><td>${x.sr!=null?x.sr.toFixed(1):'—'}</td><td>${x.hs}${x.hsno?'*':''}</td><td>${x.hundreds}/${x.fifties}</td><td>${x.wickets}</td><td>${x.bowlavg!=null?x.bowlavg.toFixed(2):'—'}</td><td>${x.econ!=null?x.econ.toFixed(2):'—'}</td><td>${x.bbw?x.bbw+'/'+x.bbr:'—'}</td></tr>`).join('')}</table></div>`:''}
  <div class="h3" style="margin-top:20px"><span>Season by season</span><small>${rows.length} recorded player-seasons</small></div><div class="tablewrap"><table><tr><th>Year</th><th>Format</th><th>Team</th><th>M</th><th>Runs</th><th>Avg</th><th>HS</th><th>100/50</th><th>Wkts</th><th>BB</th><th>Ct</th></tr>${rows.slice().reverse().map(r=>`<tr${inl.includes(r)?'':' class="dim"'}><td><a href="#" data-year="${r.y}" style="color:inherit">${r.y}</a></td><td>${r.f}${r.g==='W'?' (W)':''}</td><td>${esc(r.t)}</td><td>${r.games}</td><td>${r.runs}</td><td>${r.outs?(r.runs/r.outs).toFixed(1):'—'}</td><td>${r.hs}${r.hsno?'*':''}</td><td>${r.hundreds}/${r.fifties}</td><td>${r.wickets}</td><td>${r.bbw?r.bbw+'/'+r.bbr:'—'}</td><td>${r.catches}</td></tr>`).join('')}</table></div>
  ${games.length?`<div class="h3" style="margin-top:20px"><span>Player of the match</span><small>${games.length} awards</small></div><div class="ribbon">${games.map(m=>`<i class="${m.teams.includes(team)?resClass(m,team):'D'}" title="${esc(day(m.date))} · ${esc(m.home)} v ${esc(m.away)}" data-match="${esc(m.id)}"></i>`).join('')}</div>`:''}
  <p class="small dim" style="margin-top:12px">${p.espn?`<a href="https://www.espncricinfo.com/cricketers/${esc(p.espn)}" target="_blank" rel="noopener">Cricinfo profile ↗</a> · `:''}figures reconstructed from recorded deliveries; a missing season is a season without a recorded scorecard, not a blank year.</p></div></div>`;}
function aggOf(rr){const a={games:0,inns:0,runs:0,balls:0,outs:0,notouts:0,fours:0,sixes:0,fifties:0,hundreds:0,binns:0,bballs:0,conceded:0,wickets:0,maidens:0,five:0,catches:0,stumps:0,runouts:0,pom:0,hs:0,hsno:false,bbw:0,bbr:0,first:9999,last:0,team:rr[0]?.t};for(const r of rr){for(const k of ['games','inns','runs','balls','outs','notouts','fours','sixes','fifties','hundreds','binns','bballs','conceded','wickets','maidens','five','catches','stumps','runouts','pom'])a[k]+=r[k]||0;if(r.hs>a.hs||(r.hs===a.hs&&r.hsno)){a.hs=r.hs;a.hsno=!!r.hsno;}if(r.bbw>a.bbw||(r.bbw===a.bbw&&r.bbw&&r.bbr<a.bbr)){a.bbw=r.bbw;a.bbr=r.bbr;}a.first=Math.min(a.first,r.y);a.last=Math.max(a.last,r.y);}return {...a,batavg:a.outs?a.runs/a.outs:null,bowlavg:a.wickets?a.conceded/a.wickets:null,sr:a.balls?100*a.runs/a.balls:null,econ:a.bballs?6*a.conceded/a.bballs:null};}

/* ---------- Grounds ---------- */
function groundsView(){const list=groundModel().sort((a,b)=>b.count-a.count||a.name.localeCompare(b.name));const unrec=eraMatches().filter(m=>!m.v||!VENUES[m.v]).length;
  $('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Grounds · ${esc(eraLabel())}</span><small>${list.length} venues${unrec?' · '+fmt(unrec)+' matches without a recorded ground':''}</small></div><div class="tablewrap"><table><tr><th>Ground</th><th>City</th><th>Matches</th><th>Years</th><th>Most wins</th></tr>${list.map(c=>`<tr><td><a href="#" data-ground="${esc(c.cid)}" style="color:inherit">${esc(c.name)}</a>${c.locationOnly?' <span class="dim">(city only)</span>':''}</td><td>${esc(c.place)}</td><td>${c.count}</td><td>${c.first}${c.last!==c.first?'–'+c.last:''}</td><td>${c.top?`<i class="dot" style="${teamVar(c.top)}"></i>${esc(c.top)} (${c.wins[c.top]})`:'—'}</td></tr>`).join('')}</table></div>`;}
function groundView(cid){const g=VENUES[cid];const ms=eraMatches().filter(m=>m.v===cid);const back=`<button type="button" class="btn" data-tab="grounds">← All grounds</button>`;
  if(!g||!ms.length){$('#view').innerHTML=`<div style="margin-top:22px">${back}</div><p class="muted" style="margin-top:16px">${esc(g?.n||cid)} staged no match in ${esc(eraLabel())}.</p>`;return;}
  const st=natStats(ms);const wins={};for(const m of ms)if(m.winner)wins[m.winner]=(wins[m.winner]||0)+1;const topW=Object.entries(wins).sort((a,b)=>b[1]-a[1]);
  const tot=[];for(const m of ms)for(const i of m.sc||[])if(!i[6])tot.push({m,i});const hi=tot.sort((a,b)=>b.i[1]-a.i[1])[0];const last=ms[ms.length-1];const byF=FORMATS.map(f=>[f,ms.filter(m=>m.f===f).length]).filter(x=>x[1]);
  const ribbon=ms.map(m=>`<i style="--c:${m.winner?color(m.winner):'#333'}" title="${esc(day(m.date))} · ${esc(m.home)} v ${esc(m.away)} · ${esc(resultLine(m))}" data-match="${esc(m.id)}"></i>`).join('');
  $('#view').innerHTML=`<div style="margin-top:22px;display:flex;gap:10px;flex-wrap:wrap;align-items:center">${back}<span class="small muted">${esc(eraLabel())}</span></div>
  <div class="card" style="margin-top:18px;grid-template-columns:1fr;${topW[0]?teamVar(topW[0][0]):''}"><div><p class="eyebrow">Ground · ${esc(g.city||'')}${g.locationOnly?' · recorded as a city only':''}</p><h2 class="display" style="font-size:clamp(36px,5.6vw,76px);margin:6px 0 0">${esc(g.n)}</h2>${g.aliases&&g.aliases.length>1?`<p class="muted" style="margin:4px 0 0">${esc(g.aliases.filter(x=>x!==g.n).slice(0,4).join(' · '))}</p>`:''}
  <div class="kpis" style="margin-top:18px"><div class="kpi"><span>Matches</span><b>${ms.length}</b><small>${ms[0].year}–${last.year} · ${byF.map(x=>x[1]+' '+x[0]).join(' · ')}</small></div><div class="kpi"><span>Most wins</span><b style="font-size:22px">${topW[0]?esc(topW[0][0]):'—'}</b><small>${topW[0]?topW[0][1]+' of '+ms.length:''}</small></div><div class="kpi"><span>Highest total</span><b>${hi?scoreStr(hi.i):'—'}</b><small>${hi?esc(hi.i[0])+' · '+hi.m.year:'no scorecards'}</small></div><div class="kpi"><span>Sides</span><b>${st.length}</b><small>have played here</small></div><div class="kpi"><span>Drawn / tied</span><b>${ms.filter(m=>m.draw).length}</b><small>${ms.filter(m=>m.nr).length} no result</small></div></div>
  <div class="h3" style="margin-top:20px"><span>Winners, match by match</span><small>one block per match, in the winner’s colour</small></div><div class="ribbon">${ribbon}</div></div></div>
  <div class="two" style="margin-top:20px"><div class="panel"><div class="h3"><span>Most wins here</span></div>${natBars(topW.slice(0,8).map(([id,n])=>{const a=st.find(x=>x.id===id);return {id,w:n,l:a.l,d:a.d,nr:a.nr,p:a.p};}),a=>a.w,a=>`${a.p} matches here`,topW[0]?.[1])}</div><div class="panel"><div class="h3"><span>Records here</span><small>by win rate, 3+ matches</small></div>${natBars(st.filter(a=>a.p>=3).sort((a,b)=>b.rate-a.rate||b.w-a.w).slice(0,8),a=>a.rate,a=>`${a.p} matches`,100,'%')}</div></div>
  <div class="panel" style="margin-top:20px"><div class="h3"><span>Every match here</span></div><div class="tablewrap"><table><tr><th>Date</th><th>Format</th><th>Sides</th><th>Scores</th><th>Result</th></tr>${ms.slice().reverse().map(m=>`<tr><td><a href="#" data-match="${esc(m.id)}" style="color:inherit">${esc(day(m.date))}</a></td><td>${esc(m.f)}</td><td><i class="dot" style="${teamVar(m.home)}"></i>${esc(m.home)} v <i class="dot" style="${teamVar(m.away)}"></i>${esc(m.away)}</td><td>${esc(sides(m,m.home))}${sides(m,m.home)&&sides(m,m.away)?' · ':''}${esc(sides(m,m.away))}</td><td>${esc(resultLine(m))}</td></tr>`).join('')}</table></div></div>`;}

/* ---------- Records ---------- */
function recordsView(){const ms=eraMatches();const st=natStats(ms);const pl=playerAgg();const grounds=new Set(ms.filter(m=>m.recorded).map(m=>m.v)).size;const cups=CHAMPS.filter(c=>c.g===state.gender&&inEraYear(c.y)&&(state.fmt==='all'||c.f===state.fmt));
  const byRuns=[...ms].filter(m=>m.marginN&&m.marginN.by==='run').sort((a,b)=>b.marginN.n-a.marginN.n).slice(0,8);const byWk=[...ms].filter(m=>m.marginN&&m.marginN.by==='wicket').sort((a,b)=>b.marginN.n-a.marginN.n||a.date.localeCompare(b.date)).slice(0,8);
  const tot=[];for(const m of ms)for(const i of m.sc||[])if(!i[6])tot.push({m,i});const hi=tot.sort((a,b)=>b.i[1]-a.i[1]).slice(0,8);const lo=tot.filter(x=>x.i[2]>=10).sort((a,b)=>a.i[1]-b.i[1]).slice(0,8);
  const streaks=[...st].sort((a,b)=>b.streak-a.streak||b.rate-a.rate).slice(0,5);const draws=ms.filter(m=>m.draw).length;const ties=ms.filter(m=>m.result==='tie').length;
  const top=(k,min)=>{const rows=st.filter(a=>a.p>=min).sort((a,b)=>b[k]-a[k]||b.w-a.w).slice(0,5);return natBars(rows,a=>a[k],a=>`${a.p} matches`,Math.max(1,...rows.map(a=>a[k])),/rate/.test(k)?'%':'');};
  const ptop=(k,min,minK)=>{const rows=pl.filter(p=>p[k]!=null&&(!minK||p[minK]>=min)).sort(k==='bowlavg'?(a,b)=>a[k]-b[k]:(a,b)=>b[k]-a[k]).slice(0,5);const max=Math.max(1,...rows.map(p=>p[k]));return `<div class="board">${rows.map((p,i)=>`<button type="button" class="bar" data-player="${esc(p.id)}" style="--i:${i};${teamVar(p.team)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(pname(p.id))}<small> ${esc(code(p.team))} · ${p.first}–${p.last}</small></span></span><span class="trk"><span class="fill" style="--w:${Math.round(100*(k==='bowlavg'?rows[0][k]/p[k]:p[k]/max))}%"></span></span></span><span class="val">${/avg/.test(k)?p[k].toFixed(2):fmt(p[k])}</span></button>`).join('')}</div>`;};
  const mlist=(arr,lab)=>`<div class="board">${arr.map((m,i)=>`<button type="button" class="bar" data-match="${esc(m.id)}" style="--i:${i};${teamVar(m.winner||m.home)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(m.winner)}<small> v ${esc(m.loser)}</small></span><small>${esc(day(m.date))} · ${esc(m.f)}${m.recorded?' · '+esc(groundName(m.v)):''}</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*lab(m)/(lab(arr[0])||1))}%"></span></span></span><span class="val">${esc(m.margin)}</span></button>`).join('')}</div>`;
  const tlist=arr=>`<div class="board">${arr.map((x,i)=>`<button type="button" class="bar" data-match="${esc(x.m.id)}" style="--i:${i};${teamVar(x.i[0])}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(x.i[0])}<small> v ${esc(x.m.home===x.i[0]?x.m.away:x.m.home)}</small></span><small>${esc(day(x.m.date))} · ${esc(x.m.f)}${x.m.recorded?' · '+esc(groundName(x.m.v)):''}</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*x.i[1]/(arr[0].i[1]||1))}%"></span></span></span><span class="val">${esc(scoreStr(x.i))}</span></button>`).join('')}</div>`;
  const rec=(t,v,sub)=>`<div class="kpi"><span>${t}</span><b style="font-size:24px">${v}</b><small>${sub}</small></div>`;const hs=pl.filter(p=>p.hs).sort((a,b)=>b.hs-a.hs)[0];const bb=pl.filter(p=>p.bbw).sort((a,b)=>b.bbw-a.bbw||a.bbr-b.bbr)[0];
  $('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Records · ${esc(eraLabel())}</span><small>${fmt(ms.length)} matches</small></div>
  <div class="kpis"><div class="kpi"><span>Matches</span><b>${fmt(ms.length)}</b><small>${eraSeasons().length} seasons · ${grounds} grounds</small></div><div class="kpi"><span>Sides</span><b>${st.length}</b><small>${st.filter(a=>nat(a.id).major).length} full members</small></div><div class="kpi"><span>ICC titles</span><b>${cups.length}</b><small>${[...new Set(cups.flatMap(c=>c.w))].length} different champions</small></div><div class="kpi"><span>Drawn or tied</span><b>${draws}</b><small>${ties} ties · ${ms.filter(m=>m.nr).length} no result</small></div><div class="kpi"><span>Scorecards</span><b>${fmt(ms.filter(m=>m.detail).length)}</b><small>matches with recorded deliveries</small></div></div>
  <div class="kpis" style="margin-top:12px">${byRuns[0]?rec('Biggest win by runs',esc(byRuns[0].margin),`${esc(byRuns[0].winner)} v ${esc(byRuns[0].loser)} · ${byRuns[0].year}`):''}${hi[0]?rec('Highest total',esc(scoreStr(hi[0].i)),`${esc(hi[0].i[0])} · ${hi[0].m.year}`):''}${lo[0]?rec('Lowest all-out total',esc(scoreStr(lo[0].i)),`${esc(lo[0].i[0])} · ${lo[0].m.year}`):''}${hs?rec('Highest score',`${hs.hs}${hs.hsno?'*':''}`,`${esc(pname(hs.id))}`):''}${bb?rec('Best bowling',`${bb.bbw}/${bb.bbr}`,`${esc(pname(bb.id))}`):''}${streaks[0]?rec('Longest winning run',streaks[0].streak,`${esc(streaks[0].id)}`):''}</div>
  <div class="three" style="margin-top:20px"><div class="panel"><div class="h3"><span>Wins</span><small>sides</small></div>${top('w',0)}<div class="h3" style="margin-top:16px"><span></span><small>win rate · 20+ matches</small></div>${top('rate',20)}</div><div class="panel"><div class="h3"><span>Runs</span><small>recorded figures</small></div>${ptop('runs')}<div class="h3" style="margin-top:16px"><span></span><small>batting average · 20+ innings</small></div>${ptop('batavg',20,'inns')}</div><div class="panel"><div class="h3"><span>Wickets</span></div>${ptop('wickets')}<div class="h3" style="margin-top:16px"><span></span><small>bowling average · 20+ wickets</small></div>${ptop('bowlavg',20,'wickets')}</div></div>
  <div class="two" style="margin-top:20px"><div class="panel"><div class="h3"><span>Biggest wins by runs</span></div>${mlist(byRuns,m=>m.marginN.n)}</div><div class="panel"><div class="h3"><span>Biggest wins by wickets</span><small>ten-wicket wins, earliest first</small></div>${mlist(byWk,m=>m.marginN.n)}</div></div>
  <div class="two" style="margin-top:20px"><div class="panel"><div class="h3"><span>Highest totals</span></div>${tlist(hi)}</div><div class="panel"><div class="h3"><span>Lowest all-out totals</span></div>${tlist(lo)}</div></div>
  <div class="panel" style="margin-top:20px"><div class="h3"><span>Longest winning runs</span></div>${natBars(streaks,a=>a.streak,a=>`${a.p} matches · ${a.rate}% won`,streaks[0]?.streak)}</div>`;}

/* ---------- Barcode ---------- */
const HEATMETRICS={rate:['Win rate %','Wins divided by matches that year.'],w:['Wins','Matches won that year.'],p:['Matches','Matches played that year.'],hi:['Highest total','Highest innings total that year.']};
function barcodeView(){const seasons=eraSeasons();const metric=state.heat;const per={};for(const s of seasons){for(const a of natStats(s.matches)){const v=a[metric];per[a.id]=per[a.id]||{id:a.id,cells:{},total:0,p:0};per[a.id].cells[s.year]=v;per[a.id].total+=metric==='rate'?a.w:metric==='hi'?0:v;per[a.id].p+=a.p;}}
  const rows=Object.values(per).sort((a,b)=>b.p-a.p).slice(0,28);const max=Math.max(1,...rows.flatMap(r=>Object.values(r.cells)));const years=seasons.map(s=>s.year);
  $('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Season barcode · ${esc(eraLabel())}</span><small>${rows.length} sides × ${years.length} seasons</small></div><div class="panel"><div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:14px"><select id="heatMetric">${Object.entries(HEATMETRICS).map(([k,v])=>`<option value="${k}" ${k===metric?'selected':''}>${v[0]}</option>`).join('')}</select><span class="small muted">${esc(HEATMETRICS[metric][1])} Brightness is the cell’s share of the brightest cell; colour is the side’s. Rows ordered by matches played.</span></div>
  <div class="barcode"><div class="bc-row"><span></span><span class="cells" style="gap:2px">${years.map(y=>`<i style="background:none;height:14px;font-size:8px;color:var(--dim);text-align:center;line-height:14px">${years.length<=30||y%10===0?String(y).slice(2):''}</i>`).join('')}</span><span></span></div>${rows.map(r=>`<div class="bc-row"><span class="lab" data-nation="${esc(r.id)}">${esc(r.id)}</span><span class="cells">${years.map(y=>{const v=r.cells[y];const a=v===undefined?0:Math.max(.12,v/max);return `<i style="--c:${v===undefined?'#0e1014':mixHex(color(r.id),'#12141a',a)}" title="${y} · ${esc(r.id)} · ${v===undefined?'no match':fmt(v)+(metric==='rate'?'%':'')}"></i>`;}).join('')}</span><span class="tot">${metric==='hi'?'':fmt(Math.round(r.total))}</span></div>`).join('')}</div>
  <div class="bc-key"><span><i style="--c:#0e1014"></i>no match</span><span><i style="--c:#2a2f39"></i>low</span><span><i style="--c:var(--accent)"></i>high, in the side’s colour</span></div></div>`;}

/* ---------- Duel ---------- */
function swingChart(ms,a,b){const W=800,H=180,padL=30,padR=30,padT=16,padB=22;let cum=0;const pts=ms.map(m=>{cum+=m.winner===a?1:m.winner===b?-1:0;return cum;});const max=Math.max(1,...pts.map(Math.abs));const x=i=>padL+(ms.length>1?i*(W-padL-padR)/(ms.length-1):(W-padL-padR)/2),y=v=>padT+(H-padT-padB)*(1-v/max)/2;
  const d=pts.map((v,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(v).toFixed(1)).join('');const zero=y(0);const area=`${d}L${x(ms.length-1).toFixed(1)} ${zero}L${x(0).toFixed(1)} ${zero}Z`;const cid='sw'+Math.random().toString(36).slice(2,7);
  return `<svg viewBox="0 0 ${W} ${H}" class="swing" role="img" aria-label="Cumulative lead in the rivalry"><defs><clipPath id="${cid}a"><rect x="0" y="0" width="${W}" height="${zero}"/></clipPath><clipPath id="${cid}b"><rect x="0" y="${zero}" width="${W}" height="${H-zero}"/></clipPath></defs><line x1="${padL}" x2="${W-padR}" y1="${zero}" y2="${zero}" stroke="#2e333d"/><text x="${padL}" y="${padT-4}" class="lb" fill="${color(a)}">${esc(a)} ahead</text><text x="${padL}" y="${H-6}" class="lb" fill="${color(b)}">${esc(b)} ahead</text><path d="${area}" fill="${color(a)}" opacity=".22" clip-path="url(#${cid}a)"/><path d="${area}" fill="${color(b)}" opacity=".22" clip-path="url(#${cid}b)"/><path d="${d}" fill="none" stroke="var(--ink)" stroke-width="1.6"/>${ms.map((m,i)=>`<circle cx="${x(i).toFixed(1)}" cy="${y(pts[i]).toFixed(1)}" r="3" fill="${m.winner?color(m.winner):'#8b9099'}" data-match="${esc(m.id)}" style="cursor:pointer"><title>${esc(day(m.date))} · ${esc(m.f)} · ${esc(resultLine(m))}</title></circle>`).join('')}</svg>`;}
function duelView(){const by=state.duelBy;
  if(by==='p'){const pool=playerAgg().sort((a,b)=>b.runs+b.wickets*20-(a.runs+a.wickets*20));if(!pool.find(p=>p.id===state.dA))state.dA=pool[0]?.id;if(!pool.find(p=>p.id===state.dB)||state.dB===state.dA)state.dB=pool.find(p=>p.id!==state.dA)?.id;const opt=v=>pool.slice(0,400).map(p=>`<option value="${esc(p.id)}" ${p.id===v?'selected':''}>${esc(pname(p.id))} (${esc(code(p.team))})</option>`).join('');const P1=pool.find(p=>p.id===state.dA),P2=pool.find(p=>p.id===state.dB);
    $('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Head to head · ${esc(eraLabel())}</span><small>${fmt(pool.length)} players with recorded figures</small></div><div class="panel"><div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:16px"><select id="duelBy"><option value="n">Teams</option><option value="p" selected>Players</option></select><select id="dA">${opt(state.dA)}</select><span class="eyebrow">vs</span><select id="dB">${opt(state.dB)}</select></div><div id="duelBody"></div></div>`;if(!P1||!P2)return;
    const rowsK=[['Matches','games'],['Runs','runs'],['Batting average','batavg'],['Strike rate','sr'],['Hundreds','hundreds'],['Fifties','fifties'],['Highest score','hs'],['Wickets','wickets'],['Bowling average','bowlavg'],['Economy','econ'],['Five-fors','five'],['Catches','catches'],['Player of the match','pom']];
    $('#duelBody').innerHTML=`<div class="two" style="gap:12px"><div class="kpi" style="border-color:${color(P1.team)}"><span>${esc(pname(P1.id))}</span><b>${fmt(P1.runs)} · ${P1.wickets}</b><small>runs · wickets · ${esc(P1.team)} · ${P1.first}–${P1.last}</small></div><div class="kpi" style="border-color:${color(P2.team)}"><span>${esc(pname(P2.id))}</span><b>${fmt(P2.runs)} · ${P2.wickets}</b><small>runs · wickets · ${esc(P2.team)} · ${P2.first}–${P2.last}</small></div></div>
    <div class="tablewrap" style="margin-top:14px"><table><tr><th style="text-align:right;color:${color(P1.team)}">${esc(pname(P1.id))}</th><th></th><th style="color:${color(P2.team)}">${esc(pname(P2.id))}</th></tr>${rowsK.map(([l,k])=>{const va=P1[k],vb=P2[k];const m=Math.max(va||0,vb||0,1);const f=v=>v==null?'—':/avg|rate|econ/i.test(l)?v.toFixed(2):fmt(v);const bar=(v,c,right)=>v==null?'':`<span style="display:inline-block;height:8px;width:${Math.round(120*v/m)}px;background:${c};border-radius:2px;vertical-align:middle;margin-${right?'left':'right'}:8px"></span>`;return `<tr><td style="text-align:right">${bar(va,color(P1.team))}<b>${f(va)}</b></td><td style="text-align:center;color:var(--muted);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase">${l}</td><td><b>${f(vb)}</b>${bar(vb,color(P2.team),true)}</td></tr>`;}).join('')}</table></div><p class="small dim" style="margin-top:10px">Recorded figures in the lens, not complete careers.</p>`;return;}
  const ms=eraMatches();const all=natStats(ms).filter(a=>a.p>=5).sort((a,b)=>b.p-a.p);if(!all.find(a=>a.id===state.dA))state.dA=all[0]?.id;if(!all.find(a=>a.id===state.dB)||state.dB===state.dA)state.dB=all.find(a=>a.id!==state.dA&&ms.some(m=>m.teams.includes(state.dA)&&m.teams.includes(a.id)))?.id||all.find(a=>a.id!==state.dA)?.id;
  const opt=v=>all.map(a=>`<option value="${esc(a.id)}" ${a.id===v?'selected':''}>${esc(a.id)}</option>`).join('');const NA=all.find(a=>a.id===state.dA),NB=all.find(a=>a.id===state.dB);
  $('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Head to head · ${esc(eraLabel())}</span><small>${all.length} sides with 5+ matches</small></div><div class="panel"><div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:16px"><select id="duelBy"><option value="n" selected>Teams</option><option value="p">Players</option></select><select id="dA">${opt(state.dA)}</select><span class="eyebrow">vs</span><select id="dB">${opt(state.dB)}</select></div><div id="duelBody"></div></div>`;if(!NA||!NB)return;
  const meet=ms.filter(m=>m.teams.includes(NA.id)&&m.teams.includes(NB.id));const aw=meet.filter(m=>m.winner===NA.id).length,bw=meet.filter(m=>m.winner===NB.id).length,dr=meet.filter(m=>m.draw).length,nr=meet.filter(m=>m.nr).length;
  const norm=normAxes(all);const rowsK=[['Wins','w'],['Win rate %','rate'],['Matches','p'],['Highest total','hi'],['Best run','streak'],['ICC titles','cups']];
  $('#duelBody').innerHTML=`<div class="card" style="grid-template-columns:300px 1fr;--team:${color(NA.id)};--team2:${color(NB.id)}"><div class="trace" id="duelTrace"></div><div>
  <div class="two" style="gap:12px"><div class="kpi" style="border-color:${color(NA.id)}"><span>${esc(NA.id)}</span><b>${aw}</b><small>wins in ${meet.length} meetings${dr?' · '+dr+' drawn or tied':''}${nr?' · '+nr+' no result':''}</small></div><div class="kpi" style="border-color:${color(NB.id)}"><span>${esc(NB.id)}</span><b>${bw}</b><small>wins in ${meet.length} meetings</small></div></div>
  ${meet.length?`<div class="h3" style="margin-top:16px"><span>The rivalry, match by match</span><small>cumulative lead · click a point to open the match</small></div><div class="swingwrap">${swingChart(meet,NA.id,NB.id)}</div><div class="ribbon" style="margin-top:8px">${meet.slice(-40).map(m=>`<i class="${m.nr?'N':m.draw?'D':m.winner===NA.id?'W':'L'}" title="${esc(day(m.date))} · ${esc(m.f)} · ${esc(resultLine(m))}" data-match="${esc(m.id)}"></i>`).join('')}</div><p class="small dim" style="margin:6px 0 0">Last ${Math.min(40,meet.length)} meetings from ${esc(NA.id)}’s side.</p>`:`<p class="muted small" style="margin-top:14px">These two have not met in ${esc(eraLabel())}.</p>`}
  <div class="tablewrap" style="margin-top:14px"><table><tr><th style="text-align:right;color:${color(NA.id)}">${esc(NA.id)}</th><th style="text-align:center"></th><th style="color:${color(NB.id)}">${esc(NB.id)}</th></tr>${rowsK.map(([l,k])=>{const va=NA[k],vb=NB[k];const m=Math.max(va,vb,1);return `<tr><td style="text-align:right"><span style="display:inline-block;height:8px;width:${Math.round(120*va/m)}px;background:${color(NA.id)};border-radius:2px;vertical-align:middle;margin-right:8px"></span><b>${fmt(va)}${/rate/.test(k)?'%':''}</b></td><td style="text-align:center;color:var(--muted);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase">${l}</td><td><b>${fmt(vb)}${/rate/.test(k)?'%':''}</b><span style="display:inline-block;height:8px;width:${Math.round(120*vb/m)}px;background:${color(NB.id)};border-radius:2px;vertical-align:middle;margin-left:8px"></span></td></tr>`;}).join('')}</table></div>
  <p class="small dim" style="margin-top:10px">Whole-lens figures for each side against everyone; the meetings count and the swing are head to head.</p></div></div>`;
  radar($('#duelTrace'),AXES,norm(NA),norm(NB));}

/* ---------- Sources & coverage ---------- */
function drawSources(){const kpi=(t,v,s)=>`<div class="kpi"><span>${t}</span><b>${v}</b><small>${s}</small></div>`;const cov=A.coverage||{};const scope=cov.scope||[];
  $('#sourcesBody').innerHTML=`<p class="eyebrow">International edition / ${esc(day(A.snapshot))}</p><h2>Every international, one archive.</h2><div class="kpis">${kpi('Matches',fmt(cov.matches||MATCHES.length),'men’s and women’s Tests, ODIs and T20Is')}${kpi('With scorecards',fmt(cov.detailed||0),'ball-by-ball records, reconstructed')}${kpi('Historical results only',fmt(cov.historicOnly||0),'result, date and ground')}${kpi('Players',fmt(cov.players||Object.keys(PLAYERS).length),'with recorded figures')}${kpi('Grounds',fmt(cov.venues||Object.keys(VENUES).length),'including city-only records')}${kpi('Latest match',esc(day(A.lastDate)),'snapshot '+esc(day(A.snapshot)))}</div>
<h3>Sources</h3><ol><li><a href="https://cricsheet.org/" target="_blank" rel="noopener">Cricsheet</a> (<a href="https://opendatacommons.org/licenses/by/1-0/" target="_blank" rel="noopener">ODC-By 1.0</a>)<p>Ball-by-ball records of ${fmt(cov.detailed||0)} internationals, from which the scorecards, player figures, innings worms and line-ups are reconstructed. Coverage begins with the 2000s: ${scope.map(s=>`${s.g==='M'?'men’s':'women’s'} ${s.f} from ${esc(s.detailStart||s.start)}`).join(', ')}.</p></li><li><a href="https://www.kaggle.com/datasets/qammarshahzad/cricket-match-dataset-test-nations-18772025" target="_blank" rel="noopener">Test-nations match results 1877–2025</a> (Qammar Shahzad, Kaggle)<p>Result, date and ground for ${fmt(cov.historicOnly||0)} matches before delivery data exists; ${fmt(cov.joined||0)} records were matched to Cricsheet scorecards by date and sides, with ${(cov.conflicts||[]).length} numbering conflicts resolved by date and noted in the archive.</p></li><li><a href="https://www.icc-cricket.com/" target="_blank" rel="noopener">ICC</a><p>Champions of the ${CHAMPS.length} World Cups, T20 World Cups, Champions Trophies and World Test Championships, as published; a note marks editions decided without a final.</p></li><li><a href="https://github.com/lipis/flag-icons" target="_blank" rel="noopener">flag-icons</a> (MIT)<p>Flags; team colours are editorial.</p></li></ol>
<h3>How to read the statistics</h3><p class="small muted">Win rate is wins divided by all matches in the lens, draws, ties and no-results included. “Best record of the year” considers sides that played at least three matches and at least two-fifths of the busiest side’s calendar, and ranks them by wins minus losses, then win rate; it is a reading of the archive, not a title. The River counts each decided match once, a draw or tie as half to each side; no-results are left out. Player figures exist only where a scorecard does, so they are recorded totals within the lens, never complete careers; averages need 20 innings or 20 wickets. Super Overs are shown on the sheet but excluded from totals. Grounds recorded only as a city are marked. The men’s and women’s games are kept apart by the lens and never summed.</p>`;}

/* ---------- deep links ---------- */
let routeLock=false;
function writeRoute(){if(routeLock)return;const q=[];if(state.gender!=='M')q.push('gender='+state.gender);if(state.fmt!=='all')q.push('format='+state.fmt);if(state.era!=='all')q.push('era='+encodeURIComponent(state.era));if(state.whole)q.push('whole=1');else q.push('season='+state.year);q.push('tab='+state.tab);if(state.tab==='match'&&!state.whole&&state.match!=null)q.push('match='+encodeURIComponent(state.match));for(const k of ['nation','player','ground']){if(state.tab===k+'s'&&state[k])q.push(k+'='+encodeURIComponent(state[k]));}const h='#'+q.join('&');if(location.hash!==h){try{history.replaceState(null,'',h);}catch(e){}}}
function readRoute(){const h=location.hash.replace(/^#\/?/,'');if(!h||/^static-/.test(h))return false;const p={};for(const kv of h.split('&')){const i=kv.indexOf('=');p[i<0?kv:kv.slice(0,i)]=i<0?'1':decodeURIComponent(kv.slice(i+1));}let any=false;
  if(p.gender==='W'||p.gender==='M'){state.gender=p.gender;any=true;}if(p.format&&(p.format==='all'||FORMATS.includes(p.format))){state.fmt=p.format;any=true;}rebuildSeasons();
  if(p.era&&(p.era==='all'||ERAS.some(e=>e.id===p.era))){state.era=p.era;any=true;}
  if(p.match&&byId[p.match]){const m=byId[p.match];if(!inLens(m)){state.gender=m.g;state.fmt=state.fmt==='all'?'all':m.f;rebuildSeasons();}state.match=p.match;state.year=m.year;any=true;}else if(p.season&&byYear[+p.season]){state.year=+p.season;any=true;}
  if(state.era!=='all'&&!inEraYear(state.year)){if(p.season||p.match)state.era='all';else state.year=eraSeasons().slice(-1)[0]?.year||state.year;}
  state.whole=p.whole==='1';if(state.whole)any=true;
  if(p.tab&&TABS.some(t=>t[0]===p.tab)){state.tab=p.tab;any=true;}
  state.nation=p.nation&&MATCHES.some(m=>m.teams.includes(p.nation))?p.nation:null;state.player=p.player&&PLAYERS[p.player]?p.player:null;state.ground=p.ground&&VENUES[p.ground]?p.ground:null;
  if(!p.match||!byId[p.match])state.match=byYear[state.year]?.matches.slice(-1)[0]?.id??null;
  return any;}

/* ---------- render, navigation, events ---------- */
function render(){stopReplay();drawTabs();if(tour.stopped||!tour.timer)drawEraStrip();const v={season:seasonView,match:matchView,nations:()=>state.nation?nationView(state.nation):nationsView(),players:()=>state.player?playerView(state.player):playersView(),grounds:()=>state.ground?groundView(state.ground):groundsView(),records:recordsView,barcode:barcodeView,duel:duelView}[state.tab];try{v();}catch(e){$('#view').innerHTML=`<p class="muted">Something in this view could not be drawn: ${esc(e.message)}</p>`;console.error(e);}writeRoute();}
function go(tab,scroll=true){state.tab=tab;render();if(scroll)$('#stage').scrollIntoView({behavior:RM?'auto':'smooth',block:'start'});}
function ensureYearInLens(y){if(state.era!=='all'&&!inEraYear(y)){state.era='all';$('#eraSelect').value='all';drawGrid();}}
function setSeason(y,scroll){state.whole=false;ensureYearInLens(y);state.year=y;fillSeasons();state.match=byYear[y]?.matches.slice(-1)[0]?.id??null;applyTheme();drawRiver();if(state.tab!=='season'&&state.tab!=='match')state.tab='season';go(state.tab,scroll);}
function openMatch(id,scroll){const m=byId[id];if(!m)return;state.whole=false;if(!inLens(m)){state.gender=m.g;if(state.fmt!=='all')state.fmt=m.f;$('#gender').value=state.gender;$('#format').value=state.fmt;relens(false);}ensureYearInLens(m.year);state.year=m.year;state.match=m.id;fillSeasons();applyTheme();drawRiver();go('match',scroll);}
function fillSeasons(){const sel=$('#season');const ss=eraSeasons();if(!ss.length){sel.innerHTML='';return;}const e=state.era==='all'?null:ERAS.find(x=>x.id===state.era);sel.innerHTML=`<option value="era">${e?'Whole era':'All seasons'} · ${ss[0].year}–${ss[ss.length-1].year}</option>`+ss.slice().reverse().map(s=>`<option value="${s.year}">${s.year}</option>`).join('');sel.value=state.whole?'era':state.year;}
function setEra(id){tourStop();state.era=id;$('#eraSelect').value=id;if(id!=='all'){if(!inEraYear(state.year)){const last=eraSeasons().slice(-1)[0];state.year=last?last.year:state.year;state.match=byYear[state.year]?.matches.slice(-1)[0]?.id;}}fillSeasons();applyTheme();drawRiver();drawGrid();render();}
function relens(rerender=true){rebuildSeasons();aggCache={};if(!byYear[state.year])state.year=LAST_YEAR;state.match=byYear[state.year]?.matches.slice(-1)[0]?.id??null;state.nation=null;state.player=null;state.ground=null;fillSeasons();$('#eraSelect').innerHTML=`<option value="all">All eras · ${FIRST_YEAR}–${LAST_YEAR}</option>`+ERAS.filter(e=>e.to>=FIRST_YEAR).map(e=>`<option value="${e.id}">${esc(e.name)} · ${e.from}–${e.to}</option>`).join('');$('#eraSelect').value=state.era;if(rerender){applyTheme();drawRiver();drawGrid();render();}}
function init(){
  rebuildSeasons();
  $('#eraSelect').innerHTML=`<option value="all">All eras · ${FIRST_YEAR}–${LAST_YEAR}</option>`+ERAS.map(e=>`<option value="${e.id}">${esc(e.name)} · ${e.from}–${e.to}</option>`).join('');
  $('#theme').innerHTML=`<option value="champion">Best record’s colours</option>`+MAJOR.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');
  fillSeasons();
  const sidesN=new Set(MATCHES.flatMap(m=>m.teams)).size;
  $('#edition').innerHTML=`<span><span class="live"></span><b>${fmt(MATCHES.length)}</b> internationals</span><span><b>${sidesN}</b> sides</span><span><b>${fmt(MATCHES.filter(m=>m.detail).length)}</b> scorecards</span><span><b>${fmt(Object.keys(PLAYERS).length)}</b> players</span><span><b>${fmt(Object.keys(VENUES).length)}</b> grounds</span><span>through <b>${esc(day(A.lastDate))}</b></span>`;
  $('#reading').open=false;state.match=byYear[state.year]?.matches.slice(-1)[0]?.id;
  const deep=readRoute();if(deep){tourStop();$('#gender').value=state.gender;$('#format').value=state.fmt;$('#eraSelect').value=state.era;fillSeasons();}
  drawSources();applyTheme();drawRiver();drawGrid();render();lightsOut();if(deep&&(state.tab!=='season'||state.whole||state.era!=='all'))setTimeout(()=>$('#stage').scrollIntoView({behavior:'auto',block:'start'}),60);
  addEventListener('hashchange',()=>{if(/^#static-/.test(location.hash)){$('#reading').open=true;return;}routeLock=true;try{if(readRoute()){tourStop();$('#gender').value=state.gender;$('#format').value=state.fmt;$('#eraSelect').value=state.era;fillSeasons();applyTheme();drawRiver();drawGrid();render();}}finally{routeLock=false;}});
  $('#eraSelect').addEventListener('change',e=>setEra(e.target.value));
  $('#gender').addEventListener('change',e=>{state.gender=e.target.value;relens();});
  $('#format').addEventListener('change',e=>{state.fmt=e.target.value;relens();});
  $('#season').addEventListener('change',e=>{if(e.target.value==='era'){state.whole=true;applyTheme();drawRiver();if(state.tab!=='season'&&state.tab!=='match')state.tab='season';go(state.tab,false);}else setSeason(+e.target.value,false);});
  $('#theme').addEventListener('change',applyTheme);
  $('#gridSort').addEventListener('change',e=>{state.gridSort=e.target.value;drawGrid();});
  $('#gridMin').addEventListener('change',e=>{state.gridMin=+e.target.value;drawGrid();});
  $('#gridFind').addEventListener('input',e=>{state.gridFind=e.target.value;drawGrid();});
  $('#eraStrip').addEventListener('click',e=>{const s=e.target.closest('[data-era]');if(s)setEra(state.era===s.dataset.era?'all':s.dataset.era);});
  $('#eraStrip').addEventListener('pointerenter',()=>{tourPause();},{passive:true});$('#eraStrip').addEventListener('pointerleave',()=>{if(!tour.stopped)tourStart();},{passive:true});
  $('#eraStrip').addEventListener('mouseover',e=>{const s=e.target.closest('[data-era]');if(s&&!tour.stopped){drawEraStrip(s.dataset.era);}});
  if('IntersectionObserver' in window){new IntersectionObserver(en=>{tour.visible=en[0].isIntersecting;if(tour.visible)tourStart();else tourPause();},{threshold:.2}).observe($('#eraStrip'));}else{tour.visible=true;tourStart();}
  $('#circuits').addEventListener('click',e=>{const b=e.target.closest('[data-cid]');if(b){state.ground=b.dataset.cid;go('grounds');}});
  const clear=t=>{if(t==='nations')state.nation=null;if(t==='players')state.player=null;if(t==='grounds')state.ground=null;};
  $('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(!b)return;clear(b.dataset.tab);go(b.dataset.tab,false);});
  $('#view').addEventListener('click',e=>{const a=e.target.closest('[data-nation],[data-player],[data-ground],[data-match],[data-year],[data-tab]');if(!a)return;if(a.tagName==='A')e.preventDefault();
    if(a.dataset.tab){clear(a.dataset.tab);go(a.dataset.tab,false);return;}
    if(a.dataset.year){const y=+a.dataset.year;if(!byYear[y])return;ensureYearInLens(y);state.whole=false;state.year=y;fillSeasons();applyTheme();drawRiver();state.match=byYear[y].matches.slice(-1)[0]?.id;go('season',false);return;}
    if(a.dataset.match){openMatch(a.dataset.match,false);return;}
    if(a.dataset.nation){state.nation=a.dataset.nation;go('nations',false);return;}
    if(a.dataset.player){state.player=a.dataset.player;go('players',false);return;}
    if(a.dataset.ground){state.ground=a.dataset.ground;go('grounds',false);return;}});
  $('#view').addEventListener('change',e=>{const t=e.target;if(t.id==='lens'){state.lens=t.value;render();}else if(t.id==='plens'){state.plens=t.value;render();}else if(t.id==='heatMetric'){state.heat=t.value;render();}else if(t.id==='duelBy'){state.duelBy=t.value;state.dA=state.dB=null;render();}else if(t.id==='dA'){state.dA=t.value;render();}else if(t.id==='dB'){state.dB=t.value;render();}});
  $('#view').addEventListener('input',e=>{if(e.target.id==='find2'){state.find2=e.target.value;const pos=e.target.selectionStart;render();const f=$('#find2');if(f){f.focus();f.setSelectionRange(pos,pos);}}});
  const src=$('#sources');if(src)src.addEventListener('click',()=>{$('#sourcesBox').open=true;$('#sourcesBox').scrollIntoView({behavior:RM?'auto':'smooth'});});
  let rt;addEventListener('resize',()=>{clearTimeout(rt);rt=setTimeout(()=>{drawRiver();if(state.tab==='season')render();},150);});
}
init();
